/** Color-coded Van Season workbook. Shape, not row numbers. */

import ExcelJS from "exceljs";
import type { League } from "./model";
import { printName, teamLabel } from "./model";

export const SAMPLE_FILENAME = "Van-Season-Workbook.xlsx";
export const HEAD_SCRATCHER_FILENAME = "VSA-Head-Scratcher.xlsx";

const GREEN = "C6E5C8";
const GREEN_HDR = "2F6B3A";
const GRASS = "A8D5A2";
const GRASS_HDR = "3D6B3A";
const AMBER = "F5D08A";
const AMBER_HDR = "8A5A12";
const NAVY = "1E3A5F";
const NAVY_BAND = "D6DEE8";
const PLUM = "C4A0C8";
const PLUM_HDR = "5C2E58";
const CREAM = "F6F1E7";
const INK = "1C1917";
const WHITE = "FFFFFF";
const SAMPLE_TINT = "FFF4CC";

function fill(hex: string): ExcelJS.Fill {
  return { type: "pattern", pattern: "solid", fgColor: { argb: "FF" + hex } };
}

function font(opts: Partial<ExcelJS.Font> = {}): Partial<ExcelJS.Font> {
  return { name: "Calibri", size: 11, color: { argb: "FF" + INK }, ...opts };
}

function applyHeader(row: ExcelJS.Row, bg: string, fg = WHITE) {
  row.eachCell((cell) => {
    cell.fill = fill(bg);
    cell.font = font({ bold: true, color: { argb: "FF" + fg } });
    cell.alignment = { wrapText: true, vertical: "middle" };
    cell.border = {
      top: { style: "thin", color: { argb: "FFD0C8B8" } },
      bottom: { style: "thin", color: { argb: "FFD0C8B8" } },
      left: { style: "thin", color: { argb: "FFD0C8B8" } },
      right: { style: "thin", color: { argb: "FFD0C8B8" } },
    };
  });
  row.height = 28;
}

function paintRange(ws: ExcelJS.Worksheet, r1: number, c1: number, r2: number, c2: number, hex: string) {
  for (let r = r1; r <= r2; r++) {
    for (let c = c1; c <= c2; c++) {
      const cell = ws.getCell(r, c);
      if (!cell.fill || (cell.fill as ExcelJS.FillPattern).fgColor?.argb === "FFFFFFFF") {
        cell.fill = fill(hex);
      }
    }
  }
}

function note(cell: ExcelJS.Cell, text: string) {
  cell.note = text;
}

