export async function buildWorkbook(league: League): Promise<ExcelJS.Workbook> {
  const wb = new ExcelJS.Workbook();
  wb.creator = "Van Season";
  wb.created = new Date("2026-08-18");

  addReadMe(wb);
  addAgeGroups(wb, league);
  addFieldTypes(wb, league);
  addFields(wb, league);
  addCampuses(wb, league);
  addAssociations(wb, league);
  addTravel(wb, league);
  addFamilies(wb, league);
  addStaff(wb, league);
  addTeams(wb, league);
  addSeason(wb, league);
  addPreferred(wb, league);
  addCarveOuts(wb, league);
  return wb;
}

export async function workbookBuffer(league: League): Promise<ArrayBuffer> {
  const wb = await buildWorkbook(league);
  const buf = await wb.xlsx.writeBuffer();
  return buf as ArrayBuffer;
}

function addReadMe(wb: ExcelJS.Workbook) {
  const ws = wb.addWorksheet("Read me", { properties: { tabColor: { argb: "FF" + CREAM } } });
  ws.getColumn(1).width = 110;
  READ_ME.forEach((line, i) => {
    const cell = ws.getCell(i + 1, 1);
    cell.value = line;
    cell.font = font({
      size: i === 0 ? 16 : 12,
      bold: i === 0,
      italic: i > 0 && !line.startsWith("Put") && !/^\d+\./.test(line) && line.length > 0 && i < 4,
      name: i === 0 ? "Georgia" : "Calibri",
    });
    cell.fill = fill(CREAM);
    cell.alignment = { wrapText: true };
    if (line) ws.getRow(i + 1).height = i === 0 ? 24 : 18;
  });
}

function addAgeGroups(wb: ExcelJS.Workbook, league: League) {
  const ws = wb.addWorksheet("Age groups", { properties: { tabColor: { argb: "FF" + GREEN_HDR } } });
  const headers = [
    "Age group",
    "Minimum on the field",
    "Maximum on the field",
    "Game length",
    "Assistant referees min",
    "Assistant referees preferred",
    "Acceptable field classes",
    "May play with",
    "Sample?",
  ];
  ws.addRow(headers);
  applyHeader(ws.getRow(1), GREEN_HDR);
  note(ws.getCell(1, 1), "Add a row anywhere in this colored block. Do not worry about leaving a blank row; the importer looks for the shape, not the row number.");
  note(ws.getCell(1, 4), "Minutes. NTSSA/PDI clocks: 6U 32, 8U 40, 10U 50, 12U 60, 14U 70, 16U 80. Every game already has one center referee; do not add a head-ref column.");
  for (const a of league.ageGroups) {
    const row = ws.addRow([
      a.name,
      a.minOnField,
      a.maxOnField,
      a.gameLengthMinutes,
      a.assistantMin,
      a.assistantPreferred,
      a.fieldClasses.join(", "),
      a.mayPlayWith.join(", "),
      league.sampleOnly ? "yes" : "",
    ]);
    row.eachCell((c) => {
      c.fill = fill(GREEN);
      c.font = font({});
    });
  }
  headers.forEach((_, i) => {
    ws.getColumn(i + 1).width = i === 0 ? 16 : i === 6 || i === 7 ? 28 : 18;
  });
}

function addFieldTypes(wb: ExcelJS.Workbook, league: League) {
  const ws = wb.addWorksheet("Field types", { properties: { tabColor: { argb: "FF" + GRASS_HDR } } });
  ws.addRow(["Field type", "Width", "Length"]);
  applyHeader(ws.getRow(1), GRASS_HDR);
  note(ws.getCell(1, 1), "NTSSA recommended yards: small 25×35 (4v4), medium 45×65 (7v7), nine 55×80 (9v9), full 70×110 (11v11). Width is the goal line; length is the touchline.");
  for (const t of league.fieldTypes) {
    const row = ws.addRow([t.name, t.width, t.length]);
    row.eachCell((c) => {
      c.fill = fill(GRASS);
    });
  }
  ws.getColumn(1).width = 16;
  ws.getColumn(2).width = 12;
  ws.getColumn(3).width = 12;
}

function addFields(wb: ExcelJS.Workbook, league: League) {
  const ws = wb.addWorksheet("Fields", { properties: { tabColor: { argb: "FF" + GRASS_HDR } } });
  const headers = ["Field", "Type", "Campus", "Parking", "Available", "Sample?"];
  ws.addRow(headers);
  applyHeader(ws.getRow(1), GRASS_HDR);
  note(ws.getCell(1, 1), "A list, not a map. Name every pitch. Add a row anywhere in this grass block.");
  for (const f of league.fields) {
    const row = ws.addRow([f.name, f.type, f.campus, f.parking, f.availableRaw, league.sampleOnly ? "yes" : ""]);
    row.eachCell((c) => {
      c.fill = fill(GRASS);
    });
  }
  [28, 12, 20, 16, 48, 12].forEach((w, i) => {
    ws.getColumn(i + 1).width = w;
  });
}

function addCampuses(wb: ExcelJS.Workbook, league: League) {
  const ws = wb.addWorksheet("Campuses", { properties: { tabColor: { argb: "FF8A9A6A" } } });
  ws.addRow(["Campus", "Home association", "Street", "Latitude", "Longitude"]);
  applyHeader(ws.getRow(1), GRASS_HDR);
  for (const c of league.campuses) {
    ws.addRow([c.name, c.association || "", c.street || "", c.lat ?? "", c.lng ?? ""]);
  }
  [22, 20, 44, 12, 12].forEach((w, i) => {
    ws.getColumn(i + 1).width = w;
  });
}

function addAssociations(wb: ExcelJS.Workbook, league: League) {
  const ws = wb.addWorksheet("Associations", { properties: { tabColor: { argb: "FF1E3A5F" } } });
  ws.addRow(["Association", "Controlled", "Home campus"]);
  applyHeader(ws.getRow(1), NAVY);
  for (const a of league.associations) {
    ws.addRow([a.name, a.controlled ? "yes" : "no", a.homeCampus || ""]);
  }
  ws.addRow([]);
  ws.addRow(["Guest sides"]);
  ws.getCell(ws.lastRow!.number, 1).font = font({ bold: true });
  const gh = ws.addRow(["Association", "Age group", "Teams", "Games asked", "Side name", "Jersey"]);
  applyHeader(gh, NAVY);
  for (const a of league.associations) {
    for (const g of a.guestSides) {
      ws.addRow([a.name, g.ageGroup, g.teamCount, g.gamesRequested, g.name || "", g.jersey || ""]);
    }
  }
  [18, 16, 18, 14, 16, 12].forEach((w, i) => {
    ws.getColumn(i + 1).width = w;
  });
}

function addTravel(wb: ExcelJS.Workbook, league: League) {
  const ws = wb.addWorksheet("Travel", { properties: { tabColor: { argb: "FF6B3A62" } } });
  const names = league.campuses.map((c) => c.name);
  ws.addRow(["From \\ To", ...names]);
  applyHeader(ws.getRow(1), PLUM_HDR);
  for (const a of names) {
    const row = [a];
    for (const b of names) {
      if (a === b) {
        row.push("");
        continue;
      }
      const hit = league.travel.find(
        (t) =>
          (t.from === a && t.to === b) || (t.from === b && t.to === a),
      );
      row.push(hit && !hit.crowFlies && hit.minutes != null ? String(hit.minutes) : "");
    }
    ws.addRow(row);
  }
  ws.getColumn(1).width = 22;
  names.forEach((_, i) => {
    ws.getColumn(i + 2).width = 20;
  });
}

function addFamilies(wb: ExcelJS.Workbook, league: League) {
  const ws = wb.addWorksheet("Families", { properties: { tabColor: { argb: "FF8A5A12" } } });
  const headers = [
    "Family code",
    "Parent 1 first name",
    "Parent 1 last name",
    "Parent 1 print name",
    "Parent 1 phone",
    "Parent 1 coach of",
    "Parent 1 assistant of",
    "Parent 2 first name",
    "Parent 2 last name",
    "Parent 2 print name",
    "Parent 2 phone",
    "Parent 2 coach of",
    "Parent 2 assistant of",
  ];
  for (let k = 1; k <= 7; k++) {
    headers.push(`Kid ${k} first name`, `Kid ${k} last name`, `Kid ${k} bracket`, `Kid ${k} team`, `Kid ${k} jersey`);
  }
  headers.push("Vacation", "Sample?");
  ws.addRow(headers);
  applyHeader(ws.getRow(1), AMBER_HDR);
  note(ws.getCell(1, 4), "Leave this. It follows First and Last. Type here only if someone publishes under a different name.");
  note(ws.getCell(1, 1), "Ordinarily blank. Fill only to break two John Smiths.");
  for (const f of league.families) {
    const p1 = f.parents[0];
    const p2 = f.parents[1];
    const vals: (string | number)[] = [
      f.code || "",
      p1?.first || "",
      p1?.last || "",
      p1?.printName || "",
      p1?.phone || "",
      (p1?.coachOf || []).join("; "),
      (p1?.assistantOf || []).join("; "),
      p2?.first || "",
      p2?.last || "",
      p2?.printName || "",
      p2?.phone || "",
      (p2?.coachOf || []).join("; "),
      (p2?.assistantOf || []).join("; "),
    ];
    for (let k = 0; k < 7; k++) {
      const c = f.children[k];
      vals.push(c?.first || "", c?.last || "", c?.bracket || "", c?.team || "", c?.jersey || "");
    }
    vals.push(f.vacation || "", f.sample ? "yes" : "");
    const row = ws.addRow(vals);
    row.eachCell((c, col) => {
      const band = col === 1 || (col >= 14 && (Math.floor((col - 14) / 5) % 2 === 1));
      c.fill = fill(f.sample ? SAMPLE_TINT : band ? "F8E2B0" : AMBER);
    });
  }
  headers.forEach((_, i) => {
    ws.getColumn(i + 1).width = i === 0 ? 14 : 16;
  });
}

function addStaff(wb: ExcelJS.Workbook, league: League) {
  const ws = wb.addWorksheet("Staff", { properties: { tabColor: { argb: "FF8A5A12" } } });
  const headers = ["First name", "Last name", "Print name", "Phone", "Center of", "Assistant of", "Vacation", "Sample?"];
  ws.addRow(headers);
  applyHeader(ws.getRow(1), AMBER_HDR);
  note(ws.getCell(1, 3), "Leave this. It follows First and Last. Type here only if someone publishes under a different name.");
  for (const s of league.staff) {
    const row = ws.addRow([
      s.first,
      s.last,
      s.printName || "",
      s.phone || "",
      s.centerOf.join(", "),
      s.assistantOf.join(", "),
      s.vacation || "",
      s.sample ? "yes" : "",
    ]);
    row.eachCell((c) => {
      c.fill = fill(s.sample ? SAMPLE_TINT : AMBER);
    });
  }
  [16, 16, 16, 16, 36, 36, 22, 12].forEach((w, i) => {
    ws.getColumn(i + 1).width = w;
  });
}

function addTeams(wb: ExcelJS.Workbook, league: League) {
  const ws = wb.addWorksheet("Teams", { properties: { tabColor: { argb: "FF" + NAVY } } });
  ws.getColumn(1).width = 22;
  ws.getColumn(2).width = 28;
  ws.getColumn(3).width = 16;
  ws.getColumn(4).width = 22;
  let r = 1;
  for (const t of league.teams) {
    const start = r;
    const lines: [string, string][] = [
      ["Team name", t.name],
      ["Bracket", t.bracket],
      ["Association", t.association],
      ["Jersey", t.jersey],
      ["Coach first", t.coach?.first || ""],
      ["Coach last", t.coach?.last || ""],
      ["Coach phone", t.coach?.phone || ""],
      ["Assistant first", t.assistant?.first || ""],
      ["Assistant last", t.assistant?.last || ""],
      ["Assistant phone", t.assistant?.phone || ""],
      ["Will not play", t.willNotPlay.join(", ")],
      ["Will not travel to", t.willNotTravelTo.join(", ")],
      ["Away games desired", String(t.awayDesired ?? 0)],
      ["Guest games desired", String(t.guestDesired ?? 0)],
      ["Guest travel", t.guestTravel || ""],
      ["Minimum on the field", t.minOnField != null ? String(t.minOnField) : ""],
      ["Sample?", t.sample ? "yes" : ""],
    ];
    t.players.forEach((p, i) => {
      lines.push([`Kid ${i + 1}`, p.name]);
      if (p.jersey) lines.push([`Kid ${i + 1} jersey`, p.jersey]);
    });
    for (const [k, v] of lines) {
      ws.getCell(r, 1).value = k;
      ws.getCell(r, 2).value = v;
      ws.getCell(r, 1).font = font({ bold: true, color: { argb: "FF" + WHITE } });
      ws.getCell(r, 1).fill = fill(NAVY);
      ws.getCell(r, 2).fill = fill(t.sample ? SAMPLE_TINT : NAVY_BAND);
      ws.getCell(r, 2).font = font({});
      r += 1;
    }
    paintRange(ws, start, 1, r - 1, 2, NAVY_BAND);
    r += 2;
  }
}

function addSeason(wb: ExcelJS.Workbook, league: League) {
  const ws = wb.addWorksheet("Season", { properties: { tabColor: { argb: "FF" + PLUM_HDR } } });
  const s = league.season;
  const kv: [string, string][] = [
    ["Association", s.associationName],
    ["Title", s.title],
    ["Playing week starts", s.weekStarts],
    ["First playing date", s.firstRaw],
    ["Last playing date", s.lastRaw],
    ["Rematch cap", String(s.rematchCap)],
  ];
  ws.addRow(["Field", "Value"]);
  applyHeader(ws.getRow(1), PLUM_HDR);
  for (const [k, v] of kv) {
    const row = ws.addRow([k, v]);
    row.eachCell((c) => {
      c.fill = fill(PLUM);
    });
  }
  ws.addRow([]);
  const hdr = ws.addRow(["Kind", "Date", "Note"]);
  applyHeader(hdr, PLUM_HDR);
  for (const sp of s.specials) {
    const kind =
      sp.kind === "bye"
        ? "Bye"
        : sp.kind === "rain-check"
          ? "Rain check"
          : sp.kind === "interleague-home"
            ? "Interleague home"
            : "Interleague away";
    const row = ws.addRow([kind, sp.raw, sp.note || ""]);
    row.eachCell((c) => {
      c.fill = fill(PLUM);
    });
  }
  ws.getColumn(1).width = 24;
  ws.getColumn(2).width = 36;
  ws.getColumn(3).width = 48;
}

function addPreferred(wb: ExcelJS.Workbook, league: League) {
  const ws = wb.addWorksheet("Preferred slots", { properties: { tabColor: { argb: "FF" + PLUM_HDR } } });
  ws.addRow(["Bracket", "Rank", "Day", "Time", "Venue"]);
  applyHeader(ws.getRow(1), PLUM_HDR);
  for (const p of league.preferredSlots) {
    const row = ws.addRow([p.bracket, p.rank, p.day, p.time, p.venue || ""]);
    row.eachCell((c) => {
      c.fill = fill(PLUM);
    });
  }
  [16, 10, 14, 12, 28].forEach((w, i) => {
    ws.getColumn(i + 1).width = w;
  });
}

function addCarveOuts(wb: ExcelJS.Workbook, league: League) {
  const ws = wb.addWorksheet("Carve-outs", { properties: { tabColor: { argb: "FF" + PLUM_HDR } } });
  ws.addRow(["Team", "Date", "Not at", "Must use", "Every Saturday"]);
  applyHeader(ws.getRow(1), PLUM_HDR);
  note(ws.getCell(1, 1), "A small plum block. Name the club, the day, the slot you are withholding. Do not write why.");
  if (!league.carveOuts.length) {
    const row = ws.addRow(["", "", "", "", ""]);
    row.eachCell((c) => {
      c.fill = fill(PLUM);
    });
  }
  for (const c of league.carveOuts) {
    const row = ws.addRow([c.team, c.date || "", c.notAt || "", c.mustUse || "", c.everySaturday ? "yes" : ""]);
    row.eachCell((cell) => {
      cell.fill = fill(PLUM);
    });
  }
  [22, 22, 14, 14, 16].forEach((w, i) => {
    ws.getColumn(i + 1).width = w;
  });
}

export function downloadFilename(league: League | null, fallback = SAMPLE_FILENAME): string {
  if (!league) return fallback;
  if (league.sourceName && league.sourceName.toLowerCase().endsWith(".xlsx")) return league.sourceName;
  const slug = (league.season.associationName || "Van-Season").replace(/\s+/g, "-");
  return `${slug}-Fall-2026.xlsx`;
}

export { printName, teamLabel };
