<script lang="ts">
  import { rainCheckIsos, byeIsos } from "../calendar";
  import { formatLong, formatSheetDate } from "../dates";
  import { MINIMAP_CAPTION, dayEntryHtml, proposalsHtml, scoreCheap, type Genome } from "../ga";
  import type { Configuration, League } from "../model";
  import { publishedLocation } from "../publish";
  import { washCaption } from "../rain";
  import {
    diversityMatrixHtml,
    isAwayCampus,
    sheetBrackets,
    type SheetAction,
  } from "../schedule-sheet";
  import { seasonBurnLines } from "../sims";
  import { whoFillsFiat } from "../season-score";
  import SeasonGrid from "./SeasonGrid.svelte";

  let {
    league,
    cfg,
    sheetBracket,
    sheetWeek,
    ramification,
    ramificationKind,
    canUndo,
    planTop,
    proposalIndex,
    pinnedDay,
    hoverDay,
    washFrom,
    washNote,
    highlightGame,
    highlightQuery,
    onAction,
  }: {
    league: League;
    cfg: Configuration;
    sheetBracket: string;
    sheetWeek?: string;
    ramification?: string;
    ramificationKind?: "worse" | "better" | "same" | "";
    canUndo: boolean;
    planTop: Genome[];
    proposalIndex: number;
    pinnedDay?: string;
    hoverDay?: string;
    washFrom?: string;
    washNote?: string;
    highlightGame?: string;
    highlightQuery?: string;
    onAction: (a: SheetAction) => void;
  } = $props();

  function scoreLine(key: string): string {
    return cfg.scores.find((s) => s.key === key)?.text || "";
  }

  const z3 = $derived(cfg.z3Season);
  const div = $derived(cfg.diversity);
  const z3Text = $derived(scoreLine("z3") || z3?.text || "Z3 season: —");
  const divText = $derived(scoreLine("diversity") || div?.text || "Diversity: —");
  const simsText = $derived(scoreLine("sims") || "Sims judge: —");
  const brackets = $derived(sheetBrackets(cfg.games));
  const washedFrom = $derived((cfg.washouts || []).map((w) => w.fromIso));
  const weekKeys = $derived([...new Set(cfg.games.map((g) => g.dateIso))].sort());
  const rains = $derived(rainCheckIsos(league));
  const allWeeks = $derived([...new Set([...weekKeys, ...washedFrom, ...rains])].sort());
  const playDates = $derived([...new Set(cfg.games.map((g) => g.dateIso))].filter((d) => !rains.includes(d)));
  const burns = $derived(seasonBurnLines(league, cfg));
  const fiat = $derived(whoFillsFiat(league, cfg.games));
  const cells = $derived(scoreCheap(league, cfg.games).days);
  const open = $derived(pinnedDay || hoverDay);
  const openCell = $derived(cells.find((d) => d.dateIso === open));
  const focusN = $derived(
    cfg.games.filter((g) => (sheetBracket === "all" || g.ageGroup === sheetBracket) && (!sheetWeek || g.dateIso === sheetWeek))
      .length,
  );
  const planBar = $derived(planTop.length > 1 ? proposalsHtml(planTop, Math.min(proposalIndex, planTop.length - 1)) : "");
  const awayAll = $derived(cfg.games.filter((g) => isAwayCampus(publishedLocation(league, g.campus))).length);
  const minimap = $derived(
    `<div class="minimap" data-season-minimap>${cells
      .map((c) => {
        const on = open === c.dateIso ? "yes" : "no";
        const pin = pinnedDay === c.dateIso ? "yes" : "no";
        const light = 92 - Math.round(Math.max(0, Math.min(1, c.tightness)) * 72);
        return `<button type="button" class="minimap-day" data-minimap-day="${c.dateIso}" data-minimap-tightness="${Math.round(c.tightness * 100)}" data-day-open="${on}" data-day-pin="${pin}" style="background:hsl(0 0% ${light}%)" title="${formatSheetDate(c.dateIso)} · Sims ${c.score}">
          <span class="minimap-date">${formatSheetDate(c.dateIso)}</span>
          <span class="minimap-n">${c.games.length}</span>
        </button>`;
      })
      .join("")}</div><p class="minimap-caption" data-minimap-caption>${MINIMAP_CAPTION}</p>`,
  );
</script>

<article
  class="card sheet-card"
  data-card="schedule"
  data-super-view="season"
  data-engine={cfg.engine || ""}
  data-z3-verdict={cfg.z3Verdict || ""}
  data-z3-probe={cfg.z3Probe || ""}
  data-sheet-bracket={sheetBracket}
  data-sheet-week={sheetWeek || "all"}
>
  {#if cfg.diagnostics.length}
    {@const camel = cfg.diagnostics.find((d) => /camel's back|occupied|Unplayable|Z3 unsat/i.test(d))}
    <article class="card rust-card" data-card="diagnostics" data-camel={/camel's back/i.test(camel || "") ? "yes" : "no"}>
      <h3>Diagnostics</h3>
      {#each cfg.diagnostics as d}
        <p class="flag" data-diagnostic>{d}</p>
      {/each}
    </article>
  {/if}

  <div class="sheet-chrome" data-sheet-chrome>
  {#if planBar}
    {@html planBar}
  {/if}

  <div data-minimap-view>
    {@html minimap}
    <div data-day-slot>{@html dayEntryHtml(league, openCell, !!pinnedDay && pinnedDay === open)}</div>
  </div>

  <button type="button" data-see-full-schedule>See full schedule</button>

  <div class="triad" data-triad="judges">
    <p data-score="z3" title={z3Text} data-z3-cost={z3?.cost ?? ""} data-z3-score={z3?.score ?? ""}>{z3Text}</p>
    <p data-score="diversity" title={divText} data-diversity-score={div?.score ?? ""}>{divText}</p>
    <p data-score="sims" title={simsText}>{simsText}</p>
  </div>

  <div
    class="ramification {ramificationKind || ""}"
    data-ramification={ramification ? "yes" : "no"}
    data-ramification-kind={ramificationKind || ""}
  >
    {#if ramification}
      {@html ramification}
    {:else}
      <p class="meta">
        Drag a game card onto another to swap kickoff and grass, onto a TIME chip, or onto a FIELD chip. Lists are
        Saturdays — drop a card on another Saturday to move the date. Z3, diversity, and Sims re-score the whole fall
        immediately.
      </p>
    {/if}
    {#if canUndo}
      <p><button type="button" class="link" data-action="undo-swap">Undo this swap</button></p>
    {/if}
  </div>

  <div data-z3-brackets class="quiet-brackets">
    {#each z3?.brackets || [] as b}
      <p data-z3-bracket={b.bracket}>{b.text}</p>
    {/each}
  </div>

  <nav data-week-strip class="week-strip">
    <button type="button" class="chip" data-sheet-week="all" aria-current={!sheetWeek ? "true" : "false"}>Season</button>
    {#each allWeeks as d, i}
      {@const w = (cfg.washouts || []).find((x) => x.fromIso === d)}
      {@const live = (cfg.washouts || []).some((x) => x.toIso === d)}
      {@const canWash = playDates.includes(d) && !w}
      <span
        class="week-chip"
        data-week={d}
        data-week-index={i + 1}
        data-washed={w ? d : undefined}
        data-rain-live={live ? "true" : undefined}
      >
        <button type="button" class="chip" data-sheet-week={d} aria-current={sheetWeek === d ? "true" : "false"}
          >{formatSheetDate(d)}</button
        >
        {#if canWash}
          <button type="button" class="link wash-mini" data-action="wash-out" data-week={d}>wash</button>
        {/if}
        {#if w}
          <span class="meta">{washCaption(w)}</span>
        {/if}
      </span>
    {/each}
  </nav>

  {#if washFrom}
    <article class="card" data-wash-picker={washFrom}>
      <h4>Move these games to which rain check?</h4>
      {#each rains as d}
        <button type="button" class="link" data-action="rain-choice" data-rain-choice={d}>{formatLong(d)}</button>
      {/each}
      {#if washNote}
        <p class="flag" data-wash-note>{washNote}</p>
      {/if}
    </article>
  {:else}
    <div data-wash-bar>
      {#if byeIsos(league).size}
        <p class="meta" data-bye-wash="no">Bye — no games to move.</p>
      {/if}
      {#if washNote}
        <p class="flag" data-wash-note>{washNote}</p>
      {/if}
    </div>
  {/if}

  {#if sheetWeek}
    <p class="sheet-focus" data-sheet-focus={sheetWeek}>{formatLong(sheetWeek)} · {sheetBracket} · {focusN} games</p>
  {:else}
    <p class="sheet-focus" data-sheet-focus="season">Whole season · {sheetBracket === "all" ? "all brackets" : sheetBracket} · {focusN} games</p>
  {/if}

  <nav class="sheet-tabs" data-sheet-tabs>
    <button
      type="button"
      class="chip"
      data-sheet-tab="all"
      data-tab-away={awayAll}
      aria-current={sheetBracket === "all" ? "true" : "false"}>All{awayAll ? ` · ${awayAll} away` : ""}</button
    >
    {#each brackets as b}
      {@const awayN = cfg.games.filter((g) => g.ageGroup === b && isAwayCampus(publishedLocation(league, g.campus))).length}
      <button
        type="button"
        class="chip"
        data-sheet-tab={b}
        data-tab-away={awayN}
        aria-current={b === sheetBracket ? "true" : "false"}>{b}{awayN ? ` · ${awayN} away` : ""}</button
      >
    {/each}
  </nav>
  </div>

  <SeasonGrid
    {league}
    {cfg}
    bracket={sheetBracket}
    weekIso={sheetWeek}
    {highlightGame}
    {highlightQuery}
    {onAction}
  />

  <div data-sims-burns class="burns-line">
    {#if burns.length}
      <p class="flag" data-burn>{burns[0]}</p>
    {:else}
      <p class="meta" data-burn="none">no burns — every household and whistle holds</p>
    {/if}
  </div>

  <div data-fiat="who-fills">
    <h4>Fiat windows — who fills best</h4>
    {#if fiat.length}
      {#each fiat as f}
        <p data-fiat-window={f.dateIso || f.window} data-fiat-best={f.best}>{f.why}</p>
      {/each}
    {:else}
      <p class="meta">No external windows on this sitting.</p>
    {/if}
  </div>

  <details data-diversity-board>
    <summary>Diversity matrix</summary>
    {@html diversityMatrixHtml(league, cfg)}
  </details>
</article>
