/**
 * Main-thread client for the laminate-class Z3 worker.
 * The 33 MB wasm and every opt.check() run OFF the UI thread.
 * COOP/COEP (vite + web-serve) must keep the page cross-origin isolated.
 */

import type { Configuration, League } from "./model";

const WORKER_VER = typeof __Z3_WORKER_VER__ !== "undefined" ? __Z3_WORKER_VER__ : "dev";

function workerUrl(): string {
  return new URL(`z3-worker.bundle.js?v=${WORKER_VER}`, document.baseURI).href;
}

let worker: Worker | null = null;
let seq = 0;
let solvesSinceSpawn = 0;
const pending = new Map<number, { resolve: (v: Configuration) => void; reject: (e: Error) => void }>();
const RECYCLE_AFTER = 1;

function spawnWorker(): Worker {
  const w = new Worker(workerUrl());
  w.onmessage = (e: MessageEvent) => {
    const { id, ok, res, error } = e.data || {};
    const p = pending.get(id);
    if (!p) return;
    pending.delete(id);
    ok ? p.resolve(res) : p.reject(new Error(error || "the solver returned no result"));
  };
  w.onerror = (e) => {
    if (typeof e.preventDefault === "function") e.preventDefault();
    const raw = e && e.message;
    const msg =
      raw && raw !== "Uncaught [object ErrorEvent]" ? raw : "Z3 worker crashed";
    for (const p of pending.values()) p.reject(new Error(msg));
    pending.clear();
    if (worker === w) worker = null;
    try {
      w.terminate();
    } catch {
      /* ignore */
    }
  };
  return w;
}

function getWorker(): Worker {
  if (!worker) {
    worker = spawnWorker();
    solvesSinceSpawn = 0;
  }
  return worker;
}

function recycleWorker() {
  const w = worker;
  worker = null;
  solvesSinceSpawn = 0;
  if (w) {
    try {
      w.terminate();
    } catch {
      /* ignore */
    }
  }
}

function sendToWorker(league: League, name?: string): Promise<Configuration> {
  const w = getWorker();
  const id = ++seq;
  return new Promise((resolve, reject) => {
    pending.set(id, { resolve, reject });
    w.postMessage({ id, league, name });
  });
}

/** Calculate-the-schedule: real in-browser Z3. Never a JS placer. */
export async function solveInBrowser(league: League, name?: string): Promise<Configuration> {
  const plainLeague = JSON.parse(JSON.stringify(league)) as League;
  try {
    const res = await sendToWorker(plainLeague, name);
    solvesSinceSpawn += 1;
    if (pending.size === 0 && solvesSinceSpawn >= RECYCLE_AFTER) recycleWorker();
    return res;
  } catch (e) {
    const msg = String((e && (e as Error).message) || e);
    if (/memory|allocat|out of bounds|crashed/i.test(msg)) {
      recycleWorker();
      await new Promise((r) => setTimeout(r, 200));
      return sendToWorker(plainLeague, name);
    }
    throw e;
  }
}
