<script lang="ts">
  import { NTSSA_DRAW, type NtssaClass } from "../survey/units";
  import type { Field } from "../model";

  let {
    fields,
    selectedName = "",
    onMove,
    onSelect,
  }: {
    fields: Field[];
    selectedName?: string;
    onMove: (name: string, eastYd: number, southYd: number) => void;
    onSelect: (name: string) => void;
  } = $props();

  function cls(f: Field): NtssaClass {
    const t = String(f.type || "small").toLowerCase();
    if (t === "medium" || t === "nine" || t === "full") return t;
    return "small";
  }

  function size(f: Field) {
    const d = NTSSA_DRAW[cls(f)];
    return { w: d.widthYd, h: d.lengthYd };
  }

  function corners(f: Field): string {
    const { w, h } = size(f);
    const cx = east(f);
    const cy = south(f);
    const rad = ((f.headingDeg ?? 90) * Math.PI) / 180;
    const ux = Math.cos(rad);
    const uy = Math.sin(rad);
    const vx = -uy;
    const vy = ux;
    const pts = [
      [cx + ux * (h / 2) + vx * (w / 2), cy + uy * (h / 2) + vy * (w / 2)],
      [cx - ux * (h / 2) + vx * (w / 2), cy - uy * (h / 2) + vy * (w / 2)],
      [cx - ux * (h / 2) - vx * (w / 2), cy - uy * (h / 2) - vy * (w / 2)],
      [cx + ux * (h / 2) - vx * (w / 2), cy + uy * (h / 2) - vy * (w / 2)],
    ];
    return pts.map((p) => p.join(",")).join(" ");
  }

  const bounds = $derived.by(() => {
    let x0 = 0;
    let y0 = 0;
    let x1 = 80;
    let y1 = 60;
    for (const f of fields) {
      const { w, h } = size(f);
      const cx = east(f);
      const cy = south(f);
      const r = Math.max(w, h) / 2 + 6;
      x0 = Math.min(x0, cx - r);
      y0 = Math.min(y0, cy - r);
      x1 = Math.max(x1, cx + r);
      y1 = Math.max(y1, cy + r);
    }
    return { x: x0 - 8, y: y0 - 8, w: x1 - x0 + 16, h: y1 - y0 + 16 };
  });

  let drag: { name: string; dx: number; dy: number } | null = $state(null);
  let live = $state<Record<string, { x: number; y: number }>>({});
  let svg: SVGSVGElement | undefined = $state();

  function east(f: Field): number {
    return live[f.name]?.x ?? f.mapEastYd ?? 0;
  }
  function south(f: Field): number {
    return live[f.name]?.y ?? f.mapSouthYd ?? 0;
  }

  function toYd(e: PointerEvent): { x: number; y: number } {
    if (!svg) return { x: 0, y: 0 };
    const pt = svg.createSVGPoint();
    pt.x = e.clientX;
    pt.y = e.clientY;
    const m = svg.getScreenCTM();
    if (!m) return { x: 0, y: 0 };
    const p = pt.matrixTransform(m.inverse());
    return { x: p.x, y: p.y };
  }

  function down(e: PointerEvent, f: Field) {
    e.preventDefault();
    (e.currentTarget as Element).setPointerCapture(e.pointerId);
    const p = toYd(e);
    drag = { name: f.name, dx: p.x - east(f), dy: p.y - south(f) };
    onSelect(f.name);
  }

  function move(e: PointerEvent) {
    if (!drag) return;
    const p = toYd(e);
    live = { ...live, [drag.name]: { x: p.x - drag.dx, y: p.y - drag.dy } };
  }

  function up() {
    if (drag && live[drag.name]) onMove(drag.name, live[drag.name].x, live[drag.name].y);
    drag = null;
  }
</script>

<div class="field-sketch" data-field-sketch-map>
  <svg
    bind:this={svg}
    viewBox="{bounds.x} {bounds.y} {bounds.w} {bounds.h}"
    role="application"
    aria-label="Drag the pitches to lay out the complex"
    onpointermove={move}
    onpointerup={up}
    onpointercancel={up}
  >
    <rect class="yard" x={bounds.x} y={bounds.y} width={bounds.w} height={bounds.h} />
    {#each fields as f (f.name)}
      <g
        data-sketch-pitch={f.name}
        data-class={cls(f)}
        data-selected={selectedName === f.name ? "yes" : "no"}
        class:pop={true}
        onpointerdown={(e) => down(e, f)}
      >
        <polygon points={corners(f)} />
        <text x={east(f)} y={south(f)} text-anchor="middle" dominant-baseline="middle">
          {f.name.replace(/^.*Complex\s+/i, "").replace(/^Van\s+/i, "")}
        </text>
      </g>
    {/each}
  </svg>
  <p class="hint">Drag a pitch. Add another and it pops onto the map.</p>
</div>

<style>
  .field-sketch {
    background: #e7f0e4;
    border: 1px solid var(--hair, #e4d8c4);
    min-height: 220px;
  }
  svg {
    display: block;
    width: 100%;
    height: 280px;
    touch-action: none;
    cursor: grab;
  }
  .yard {
    fill: #d5e6cf;
    stroke: none;
  }
  g {
    cursor: grab;
  }
  g[data-selected="yes"] polygon {
    stroke: #c9922a;
    stroke-width: 2.2;
  }
  polygon {
    fill: #3d7a4a;
    fill-opacity: 0.88;
    stroke: #163528;
    stroke-width: 1.4;
  }
  g[data-class="medium"] polygon { fill: #2d6a3f; }
  g[data-class="nine"] polygon { fill: #1e3a5f; }
  g[data-class="full"] polygon { fill: #6b3a62; }
  text {
    fill: #fffdf8;
    font-size: 5.5px;
    font-weight: 700;
    pointer-events: none;
    font-family: "Source Sans 3", sans-serif;
  }
  .hint {
    margin: 0;
    padding: 6px 10px 8px;
    font-size: 0.82rem;
    color: var(--muted, #6b6258);
  }
  g.pop polygon {
    animation: pop 0.35s ease;
  }
  @keyframes pop {
    from { transform: scale(0.4); transform-origin: center; opacity: 0.2; }
    to { transform: scale(1); opacity: 1; }
  }
</style>
