function fill(hex: string): ExcelJS.Fill {
  return { type: "pattern", pattern: "solid", fgColor: { argb: "FF" + hex } };
}

const RUST = "9A3B2F";
const PINE = "163528";
const NAVY = "1E3A5F";

function headerRow(ws: ExcelJS.Worksheet, cols: string[], hex = NAVY) {
  const row = ws.addRow(cols);
  row.font = { bold: true, color: { argb: "FFFFFFFF" } };
  row.fill = fill(hex);
}

export function gamesForTeam(cfg: Configuration, label: string): PlacedGame[] {
  return cfg.games.filter((g) => g.home === label || g.away === label);
}

export function gamesForChild(league: League, cfg: Configuration, child: Child): PlacedGame[] {
  const team = league.teams.find((t) => t.name === child.team && t.bracket === child.bracket);
  if (!team) return [];
  return gamesForTeam(cfg, teamLabel(team));
}

function clock(raw: string): number {
  return parseClock(raw) ?? 0;
}

/** VSA / MSA / LSA / CYSA — the letters coaches already print on a grid. */
export function assocCode(association: string): string {
  const n = norm(association);
  if (/van/.test(n)) return "VSA";
  if (/mineola/.test(n)) return "MSA";
  if (/lindale/.test(n)) return "LSA";
  if (/canton/.test(n)) return "CYSA";
  if (/forney/.test(n)) return "FSA";
  const letters = association
    .replace(/soccer association/i, "")
    .trim()
    .split(/\s+/)
    .filter(Boolean)
    .map((w) => w[0])
    .join("")
    .toUpperCase();
  if (!letters) return "SA";
  return /SA$/.test(letters) ? letters : `${letters}SA`;
}

export function publishedClubName(league: League, label: string): string {
  const team = league.teams.find((t) => teamLabel(t) === label);
  if (team) return `${assocCode(team.association)} ${team.name}`;
  const guest = league.associations.flatMap((a) =>
    a.guestSides.map((g) => ({ a, g })),
  ).find(({ a, g }) => {
    const n = g.name || a.name;
    return norm(label) === norm(n) || norm(label).includes(norm(n)) || norm(label).includes(norm(a.name));
  });
  if (guest) return `${assocCode(guest.a.name)} ${guest.g.name || guest.a.name}`;
  const assoc = league.associations.find((a) => norm(label).includes(norm(a.name)));
  if (assoc) return `${assocCode(assoc.name)} ${label.replace(new RegExp(assoc.name, "i"), "").trim() || label}`;
  return label || "TBA";
}

export function publishedLocation(league: League, campus: string): string {
  if (!campus || /^tba$/i.test(campus)) return "TBA";
  if (isGuestCampus(league, campus)) {
    const street = campusStreet(league, campus);
    if (street) return street;
  }
  if (/van/i.test(campus)) return "Van";
  return campus.replace(/\s+Complex$/i, "").replace(/\s+High School.*$/i, "").trim() || "TBA";
}

export function gamesOverlap(a: PlacedGame, b: PlacedGame): boolean {
  if (a.dateIso !== b.dateIso) return false;
  const a0 = clock(a.kickoff);
  const a1 = clock(a.end) || a0 + 50;
  const b0 = clock(b.kickoff);
  const b1 = clock(b.end) || b0 + 50;
  return a0 < b1 && b0 < a1;
}

export interface FamilyWeekend {
  dateIso: string;
  away: boolean;
  rows: { child: string; team: string; game?: PlacedGame; street?: string }[];
  banner: string;
  note?: string;
  leaveBy?: string;
  travelNote?: string;
  rust: boolean;
  guestAway?: boolean;
}

function leaveByLine(child: string, kickoff: string, travel: number): string {
  const kick = clock(kickoff);
  const walkOn = kick - 15;
  const leave = walkOn - travel - 10;
  return `Leave Van by ${formatClockShort(Math.max(0, leave))} if you want ${child.split(" ")[0]} walking onto the grass at ${formatClockShort(walkOn)}`;
}

export function familyWeekends(league: League, cfg: Configuration, family: Family): FamilyWeekend[] {
  const year = seasonYear(league);
  const byes = byeIsos(league);
  const fromGames = cfg.games.map((g) => g.dateIso);
  const washed = (cfg.washouts || []).map((w) => w.fromIso);
  const sats = [...new Set([...playingSaturdays(league), ...fromGames, ...washed])].filter((d) => !byes.has(d)).sort();
  const home = homeCampusName(league);
  const out: FamilyWeekend[] = [];
  for (const dateIso of sats) {
    const away = vacationCovers(family.vacation, dateIso, year);
    const rows = family.children.map((c) => {
      const game = gamesForChild(league, cfg, c).find((g) => g.dateIso === dateIso);
      return {
        child: printName(c),
        team: `${c.bracket} ${c.team}`.trim(),
        game,
        street: game ? campusStreet(league, game.campus) : undefined,
      };
    });
    const games = rows.map((r) => r.game).filter(Boolean) as PlacedGame[];
    let rust = false;
    let banner = "One car can cover this Saturday.";
    let note: string | undefined;
    let leaveBy: string | undefined;
    let travelNote: string | undefined;
    const guestAway = games.length > 0 && games.every((g) => isGuestCampus(league, g.campus));
    const wash = (cfg.washouts || []).find((w) => w.fromIso === dateIso);
    if (away) {
      banner = "family away — you asked not to play";
    } else if (wash && !games.length) {
      banner = `No games — washed out. See ${formatLong(wash.toIso).replace(/^[^,]+, /, "")}.`;
    } else if (guestAway) {
      banner = "Away Saturday — one campus, one kickoff.";
      const g = games[0];
      const t = travelMinutes(league, home, g.campus);
      if (t.minutes != null) {
        travelNote = `${t.minutes} minutes from ${home} — from the travel sheet, not live traffic`;
        const kid = rows.find((r) => r.game === g)?.child || "";
        leaveBy = leaveByLine(kid, g.kickoff, t.minutes);
      }
    } else if (games.length >= 2) {
      const pairs: [PlacedGame, PlacedGame][] = [];
      for (let i = 0; i < games.length; i++) {
        for (let j = i + 1; j < games.length; j++) pairs.push([games[i], games[j]]);
      }
      const hit = pairs.find(([a, b]) => gamesOverlap(a, b));
      if (hit) {
        rust = true;
        const names = rows
          .filter((r) => r.game && (r.game === hit[0] || r.game === hit[1]))
          .map((r) => r.child.split(" ")[0]);
        const twoCampus = hit[0].campus !== hit[1].campus;
        banner = twoCampus
          ? `${names.join(" and ")} kick at the same time on two campuses. One adult cannot watch both.`
          : `${names.join(" and ")} kick at the same time. One adult cannot watch both.`;
      } else {
        const lots = [...new Set(games.map((g) => g.parking).filter(Boolean))];
        const campuses = [...new Set(games.map((g) => g.campus))];
        if (campuses.length === 1 && lots.length === 2) {
          note = `${lots[0]} to ${lots[1]} is a walk across ${campuses[0]} — no drive.`;
        } else if (campuses.length === 2) {
          const t = travelMinutes(league, campuses[0], campuses[1]);
          if (t.minutes != null) {
            note =
              lots.length === 2
                ? `${lots[0]} to ${lots[1]} is ${t.minutes} minutes — from the travel sheet.`
                : `${campuses[0]} to ${campuses[1]} is ${t.minutes} minutes — from the travel sheet.`;
          }
        }
      }
    }
    out.push({ dateIso, away, rows, banner, note, leaveBy, travelNote, rust, guestAway });
  }
  return out;
}

export function ownScarsLabel(scars: DocumentScars): string {
  const two = scars.familyOverlaps.find((o) => /two campuses/i.test(o.text));
  if (two) return `I will explain the two-campus overlap to the ${two.family} household`;
  if (scars.familyOverlaps[0]) return `I will explain the overlap to the ${scars.familyOverlaps[0].family}s`;
  return "I will explain the overlap to the Hales";
}

export interface DocumentScars {
  familyOverlaps: { family: string; text: string }[];
  unplayable: { text: string }[];
  simsIllegal: boolean;
}

export function documentScars(league: League, cfg: Configuration): DocumentScars {
  const familyOverlaps: DocumentScars["familyOverlaps"] = [];
  for (const f of league.families) {
    const rust = familyWeekends(league, cfg, f).filter((w) => w.rust);
    if (rust.length) {
      familyOverlaps.push({ family: familyLast(f), text: rust[0].banner });
    }
  }
  const unplayable = cfg.games
    .filter((g) => g.unplayable || !g.center)
    .map((g) => ({
      text: `UNSTAFFED — ${g.ageGroup} ${formatLong(g.dateIso)} ${g.kickoff} ${g.home} vs ${g.away}`,
    }));
  const judged = judgeSeason(league, cfg);
  for (const day of judged.days) {
    for (const t of day.score.traces) {
      if (t.verdict !== "needs-two-cars" && t.verdict !== "even-two-cars-cannot") continue;
      if (familyOverlaps.some((o) => o.family === t.subject)) continue;
      familyOverlaps.push({ family: t.subject, text: t.headline });
    }
  }
  if (!judged.legal && !unplayable.some((u) => /Sims judge/i.test(u.text))) {
    unplayable.push({ text: "Sims judge refused this Saturday — do not publish as valid" });
  }
  return { familyOverlaps, unplayable, simsIllegal: !judged.legal };
}

export function documentsHeld(scars: DocumentScars): boolean {
  return scars.familyOverlaps.length > 0 || scars.unplayable.length > 0 || scars.simsIllegal;
}

export function documentsBanner(scars: DocumentScars): string {
  if (!documentsHeld(scars)) return "";
  const bits: string[] = [];
  if (scars.familyOverlaps.length) bits.push(`${scars.familyOverlaps.length} family overlap`);
  if (scars.unplayable.length) bits.push(`${scars.unplayable.length} unplayable game`);
  if (scars.simsIllegal && !bits.some((b) => /unplayable/i.test(b))) bits.push("a Saturday the Sims judge refused");
  return `This configuration has ${bits.join(" and ")}. Family packets are held.`;
}

export function familyFileName(family: Family, year = 2026): string {
  return `${familyLast(family)}-Family-Fall-${year}.xlsx`;
}

export function playerFileName(child: Child): string {
  const n = printName(child).replace(/\s+/g, "-");
  return `${n}-${child.bracket}-${child.team}.xlsx`.replace(/\s+/g, "-");
}

const BRACKET_TABS = ["6U", "8U", "10U", "10U Girls", "12U", "14U", "14U Girls", "16U"];

function sortBrackets(brackets: string[]): string[] {
  return [...brackets].sort((a, b) => {
    const ia = BRACKET_TABS.indexOf(a);
    const ib = BRACKET_TABS.indexOf(b);
    return (ia < 0 ? 99 : ia) - (ib < 0 ? 99 : ib) || a.localeCompare(b);
  });
}

/** DATE / TIME / HOME / AWAY / LOCATION — one sheet per league, blank row between Saturdays. */
function addHandwrittenSheets(
  wb: ExcelJS.Workbook,
  league: League,
  games: PlacedGame[],
  roster: League["teams"],
): void {
  const brackets = sortBrackets([...new Set(roster.map((t) => t.bracket).filter(Boolean))]);
  for (const bracket of brackets) {
    const ws = wb.addWorksheet(bracket);
    headerRow(ws, ["DATE", "TIME", "HOME", "AWAY", "LOCATION"]);
    const side = roster.filter((t) => t.bracket === bracket);
    const labels = new Set(side.map(teamLabel));
    const seen = new Set<string>();
    const rows = games
      .filter((g) => g.ageGroup === bracket || labels.has(g.home) || labels.has(g.away))
      .filter((g) => {
        const k = g.id || `${g.dateIso}|${g.kickoff}|${g.home}|${g.away}`;
        if (seen.has(k)) return false;
        seen.add(k);
        return true;
      })
      .sort((a, b) => a.dateIso.localeCompare(b.dateIso) || clock(a.kickoff) - clock(b.kickoff) || a.home.localeCompare(b.home));
    let prevDate = "";
    for (const g of rows) {
      if (prevDate && g.dateIso !== prevDate) ws.addRow(["", "", "", "", ""]);
      prevDate = g.dateIso;
      const unstaffed = !g.center || g.unplayable;
      const row = ws.addRow([
        g.dateIso ? formatSheetDate(g.dateIso) : "TBA",
        formatSheetTime(g.kickoff),
        publishedClubName(league, g.home),
        publishedClubName(league, g.away),
        publishedLocation(league, g.campus),
      ]);
      if (unstaffed) row.font = { color: { argb: "FF" + RUST }, bold: true };
    }
    if (!rows.length) ws.addRow(["TBA", "TBA", "TBA", "TBA", "TBA"]);
    [12, 10, 28, 28, 40].forEach((w, i) => {
      ws.getColumn(i + 1).width = w;
    });
    ws.views = [{ state: "frozen", ySplit: 1 }];
  }
}

export function handwrittenFileName(league: League, year = seasonYear(league)): string {
  return `VSA-Fall-${year}-Schedule.xlsx`;
}

/** The grid coaches already keep: one sheet per league, no rain/notes tabs. */
export async function handwrittenScheduleWorkbook(
  league: League,
  games: PlacedGame[],
): Promise<ExcelJS.Workbook> {
  const wb = new ExcelJS.Workbook();
  wb.creator = "Van Season";
  addHandwrittenSheets(wb, league, games, league.teams);
  return wb;
}

export async function leagueScheduleWorkbook(
  league: League,
  cfg: Configuration,
  opts: { onlyAssociation?: string } = {},
): Promise<ExcelJS.Workbook> {
  const wb = new ExcelJS.Workbook();
  wb.creator = "Van Season";
  const roster = opts.onlyAssociation
    ? league.teams.filter((t) => norm(t.association) === norm(opts.onlyAssociation || ""))
    : league.teams;
  addHandwrittenSheets(wb, league, cfg.games, roster);

  const rain = wb.addWorksheet("Rain checks");
  rain.addRow(["Date", "Status"]);
  rain.getRow(1).font = { bold: true };
  const rainDates = league.season.specials.filter((s) => s.kind === "rain-check");
  for (const r of rainDates) {
    const iso = r.iso;
    const on = iso ? cfg.games.filter((g) => g.dateIso === iso) : [];
    if (on.length) {
      rain.addRow([r.raw || iso, `${on.length} games placed`]);
      for (const g of on.sort((a, b) => a.home.localeCompare(b.home) || a.kickoff.localeCompare(b.kickoff))) {
        rain.addRow(["", `${g.kickoff} ${g.field} ${g.home} vs ${g.away}`]);
      }
    } else {
      rain.addRow([r.raw || r.iso, "no games placed"]);
    }
  }
  if (!rainDates.length) rain.addRow(["", "no games placed"]);
  rain.getColumn(1).width = 28;
  rain.getColumn(2).width = 22;

  const notes = wb.addWorksheet("Notes");
  notes.addRow(["Configuration", cfg.name]);
  notes.addRow(["When", cfg.createdAt]);
  notes.addRow(["Hard rules", cfg.hardHeld ? "hard rules: all held" : "strain"]);
  for (const w of cfg.washouts || []) {
    notes.addRow([
      "Wash-out",
      `${cfg.name} — ${formatLong(w.fromIso)} washed out onto ${formatLong(w.toIso)} — ${cfg.hardHeld ? "hard rules: all held" : "strain"}`,
    ]);
  }
  if (cfg.stale) notes.addRow(["Status", cfg.stale.startsWith("STALE") ? cfg.stale : `STALE — ${cfg.stale}`]);
  else if (cfg.published === false) notes.addRow(["Status", `${cfg.name} — not published`]);
  const assocs = new Set(
    cfg.games.flatMap((g) =>
      [g.home, g.away].map((lab) => league.teams.find((t) => teamLabel(t) === lab)?.association || ""),
    ),
  );
  if ([...assocs].some((a) => /rec/i.test(a)) && [...assocs].some((a) => /academy/i.test(a))) {
    notes.addRow(["Leagues", "Van Rec + Van Academy on one complex"]);
  }
  for (const w of withheldMatchups(league)) notes.addRow(["Matchup withheld", `${w.a} vs ${w.b}`]);
  for (const s of cfg.scores) notes.addRow([s.key, s.text]);
  const lock = slotLockBanner(cfg);
  if (lock) notes.addRow(["Carve-out cost", lock]);
  for (const g of cfg.games) {
    for (const n of g.notes) {
      if (/cross-bracket/i.test(n)) notes.addRow(["Mix", `${g.home} vs ${g.away} — ${n}`]);
    }
  }
  notes.getColumn(1).width = 22;
  notes.getColumn(2).width = 80;

  return wb;
}

export async function familyWorkbook(league: League, cfg: Configuration, family: Family): Promise<ExcelJS.Workbook> {
  const wb = new ExcelJS.Workbook();
  wb.creator = "Van Season";
  const year = seasonYear(league);
  const cover = wb.addWorksheet("Cover");
  cover.addRow(["Family", `The ${familyLast(family)}s`]);
  for (const p of family.parents) {
    cover.addRow(["Adult", printName(p), p.phone || ""]);
  }
  for (const c of family.children) {
    cover.addRow(["Child", printName(c), `${c.bracket} ${c.team}`.trim()]);
  }
  if (family.vacation) cover.addRow(["Away", family.vacation]);
  cover.addRow(["Note", "There is no home address on this sheet."]);
  const scars = documentScars(league, cfg);
  const ours = scars.familyOverlaps.find((o) => o.family === familyLast(family));
  if (ours) {
    const row = cover.addRow(["Banner", ours.text]);
    row.font = { color: { argb: "FF" + RUST }, bold: true };
  }
  cover.getColumn(1).width = 12;
  cover.getColumn(2).width = 36;
  cover.getColumn(3).width = 22;

  const weekend = wb.addWorksheet("Weekend");
  weekend.addRow(["Date", "Child", "Team", "Kickoff", "Field", "Campus", "Parking", "Banner"]);
  weekend.getRow(1).font = { bold: true, color: { argb: "FFFFFFFF" } };
  weekend.getRow(1).fill = fill(PINE);
  for (const day of familyWeekends(league, cfg, family)) {
    if (day.away) {
      const row = weekend.addRow([formatLong(day.dateIso), "", "", "", "", "", "", day.banner]);
      row.font = { italic: true, color: { argb: "FF6B6258" } };
      continue;
    }
    const playing = day.rows.filter((r) => r.game);
    if (!playing.length) {
      const washLine = /washed out/i.test(day.banner) ? day.banner : "No games";
      const row = weekend.addRow([formatLong(day.dateIso), "", "", "", "", "", "", washLine]);
      if (/washed out/i.test(day.banner)) row.font = { italic: true, color: { argb: "FF6B6258" } };
      continue;
    }
    for (const r of playing) {
      const g = r.game!;
      const lot = day.guestAway ? `park ${g.parking}` : g.parking;
      const row = weekend.addRow([
        formatLong(g.dateIso),
        r.child,
        r.team,
        g.kickoff,
        g.field,
        g.campus,
        lot,
        day.banner,
      ]);
      if (day.rust) row.font = { color: { argb: "FF" + RUST } };
      if (r.street) weekend.addRow(["", "", "", "", "", r.street, "", ""]);
      if (g.notes.some((n) => /cross-bracket|this game is/i.test(n))) {
        const opp = g.home === r.team || g.home.endsWith(r.team) ? g.away : g.home;
        const parsed = opp.match(/^(\d+U(?:\sGirls)?)\s+(.+)$/);
        const pretty = parsed ? `${parsed[2]} (${parsed[1]})` : opp;
        const clock = g.notes.find((n) => /this game is/i.test(n)) || "this game is 40 minutes";
        weekend.addRow(["", "", "", "", "", "", "", `opponent ${pretty} — ${clock}`]);
      }
    }
    if (day.travelNote) weekend.addRow(["", "", "", "", "", "", "", day.travelNote]);
    if (day.leaveBy) weekend.addRow(["", "", "", "", "", "", "", day.leaveBy]);
    if (day.note) weekend.addRow(["", "", "", "", "", "", "", day.note]);
  }
  [22, 16, 18, 10, 14, 18, 14, 56].forEach((w, i) => {
    weekend.getColumn(i + 1).width = w;
  });
  return wb;
}

export async function playerWorkbook(league: League, cfg: Configuration, child: Child): Promise<ExcelJS.Workbook> {
  const wb = new ExcelJS.Workbook();
  const team = league.teams.find((t) => t.name === child.team && t.bracket === child.bracket);
  const family = league.families.find((f) => f.children.some((c) => printName(c) === printName(child)));
  const jersey = team?.jersey || "";
  const ws = wb.addWorksheet("Schedule");
  const title = jersey
    ? `${printName(child)} — ${child.bracket} ${child.team} — ${jersey}`
    : `${printName(child)} — ${child.bracket} ${child.team}`;
  ws.addRow([title]);
  ws.getRow(1).font = { bold: true, size: 14 };
  ws.addRow(["Date", "Kickoff", "Field", "Parking", "Opponent", "Coach", "Notes"]);
  ws.getRow(2).font = { bold: true };

  const year = seasonYear(league);
  const games = gamesForChild(league, cfg, child);
  const byes = byeIsos(league);
  const sats = [...new Set([...playingSaturdays(league), ...games.map((g) => g.dateIso)])]
    .filter((d) => !byes.has(d))
    .sort();
  const coach = team?.coach ? `Coach ${team.coach.first}` : "";
  for (const dateIso of sats) {
    if (family && vacationCovers(family.vacation, dateIso, year)) {
      ws.addRow([formatLong(dateIso), "", "", "", "", "", "family away — no game expected"]);
      continue;
    }
    const wash = (cfg.washouts || []).find((w) => w.fromIso === dateIso);
    const g = games.find((x) => x.dateIso === dateIso);
    if (!g) {
      if (wash) {
        ws.addRow([
          formatLong(dateIso),
          "",
          "",
          "",
          "",
          "",
          `No games — washed out. See ${formatLong(wash.toIso).replace(/^[^,]+, /, "")}.`,
        ]);
      } else {
        ws.addRow([formatLong(dateIso), "", "", "", "", "", ""]);
      }
      continue;
    }
    const opponent = g.home === (team ? teamLabel(team) : "") ? g.away : g.home;
    const street = campusStreet(league, g.campus);
    const bits = [street, g.campus !== "Van Complex" ? g.campus : "", isGuestCampus(league, g.campus) ? `park ${g.parking}` : ""]
      .filter(Boolean);
    ws.addRow([formatLong(g.dateIso), g.kickoff, g.field, g.parking, opponent, coach, bits.join(" — ")]);
  }
  [22, 10, 14, 14, 22, 16, 32].forEach((w, i) => {
    ws.getColumn(i + 1).width = w;
  });
  return wb;
}

export async function refereeWorkbook(league: League, cfg: Configuration): Promise<ExcelJS.Workbook> {
  const wb = new ExcelJS.Workbook();
  const refs = new Map<string, { role: string; games: PlacedGame[] }>();
  const add = (name: string, role: string, g: PlacedGame) => {
    if (!name) return;
    const cur = refs.get(name) || { role, games: [] };
    cur.games.push(g);
    refs.set(name, cur);
  };
  for (const g of cfg.games) {
    if (g.center) add(g.center, "Center", g);
    for (const a of g.assistants) add(a, "Assistant", g);
  }
  for (const s of league.staff) {
    const name = printName(s);
    if (!refs.has(name)) refs.set(name, { role: s.centerOf.length ? "Center" : "Assistant", games: [] });
  }

  const year = seasonYear(league);
  for (const s of league.staff) {
    const name = printName(s);
    const rec = refs.get(name);
    if (!rec) continue;
    const sheetName = name.slice(0, 31);
    const ws = wb.addWorksheet(sheetName);
    ws.addRow([`${name} — ${rec.role}`]);
    ws.getRow(1).font = { bold: true, size: 14 };
    ws.addRow(["Date", "Age group", "Role", "Kickoff", "Field", "Campus", "Parking", "Address", "Center", "Home", "Away"]);
    ws.getRow(2).font = { bold: true };
    const role = rec.role === "Center" || s.centerOf.length ? "Center" : "Assistant";
    const rows = rec.games
      .filter((g) => !vacationCovers(s.vacation, g.dateIso, year))
      .sort((a, b) => a.dateIso.localeCompare(b.dateIso) || a.kickoff.localeCompare(b.kickoff));
    let prev: PlacedGame | undefined;
    for (const g of rows) {
      const thisRole = g.center === name ? "Center" : "Assistant";
      if (role === "Center" && thisRole !== "Center") continue;
      if (role === "Assistant" && thisRole !== "Assistant") continue;
      if (prev && prev.dateIso === g.dateIso) {
        const gap = Math.max(0, (parseClock(g.kickoff) ?? 0) - (parseClock(prev.end) ?? parseClock(prev.kickoff) ?? 0));
        if (prev.parking && g.parking && prev.parking !== g.parking) {
          ws.addRow(["", "", "", "", "", "", "", `${gap} minutes — ${prev.parking} to ${g.parking}`, "", ""]);
        }
      }
      ws.addRow([
        formatLong(g.dateIso),
        g.ageGroup,
        thisRole,
        g.kickoff,
        g.field,
        g.campus,
        g.parking,
        campusStreet(league, g.campus) || "",
        g.center || "",
        g.home,
        g.away,
      ]);
      prev = g;
    }
    [22, 12, 12, 10, 14, 18, 14, 16, 22, 22].forEach((w, i) => {
      ws.getColumn(i + 1).width = w;
    });
  }

  const master = wb.addWorksheet("Master");
  headerRow(master, ["Date", "Field", "Campus", "Kickoff", "Age group", "Home", "Away", "Center", "Assistants"]);
  const games = [...cfg.games].sort((a, b) => a.dateIso.localeCompare(b.dateIso) || a.field.localeCompare(b.field) || a.kickoff.localeCompare(b.kickoff));
  for (const g of games) {
    const travelHole = /travel/i.test(g.unplayable || "");
    const unstaffed = !g.center || !!g.unplayable;
    const row = master.addRow([
      formatLong(g.dateIso),
      g.field,
      g.campus,
      g.kickoff,
      g.ageGroup,
      g.home,
      g.away,
      g.center || (travelHole ? "UNSTAFFED — travel" : `${g.ageGroup} — no center`),
      g.assistants.join(", ") || (unstaffed ? (travelHole ? "UNSTAFFED — travel" : "UNSTAFFED") : ""),
    ]);
    if (unstaffed) row.font = { color: { argb: "FF" + RUST }, bold: true };
  }
  [22, 14, 18, 10, 12, 22, 22, 16, 22].forEach((w, i) => {
    master.getColumn(i + 1).width = w;
  });
  return wb;
}

export async function familyZip(league: League, cfg: Configuration): Promise<Uint8Array> {
  const year = seasonYear(league);
  const files = [];
  for (const f of league.families.filter((x) => x.children.length)) {
    const wb = await familyWorkbook(league, cfg, f);
    const buf = new Uint8Array(await workbookToBuffer(wb));
    files.push({ name: familyFileName(f, year), data: buf });
  }
  return zipStore(files);
}

export async function playerZip(league: League, cfg: Configuration): Promise<Uint8Array> {
  const seen = new Set<string>();
  const files = [];
  const kids: Child[] = [];
  for (const f of league.families) {
    for (const c of f.children) {
      const k = printName(c);
      if (!k || seen.has(k)) continue;
      seen.add(k);
      kids.push(c);
    }
  }
  for (const t of league.teams) {
    for (const p of t.players) {
      if (seen.has(p.name)) continue;
      seen.add(p.name);
      const [first, ...rest] = p.name.split(" ");
      kids.push({ first, last: rest.join(" "), bracket: t.bracket, team: t.name, jersey: p.jersey });
    }
  }
  for (const c of kids) {
    const wb = await playerWorkbook(league, cfg, c);
    files.push({ name: playerFileName(c), data: new Uint8Array(await workbookToBuffer(wb)) });
  }
  return zipStore(files);
}

export function firstSaturdayGames(cfg: Configuration): PlacedGame[] {
  const first = [...cfg.games].map((g) => g.dateIso).sort()[0];
  return cfg.games.filter((g) => g.dateIso === first);
}

export async function workbookToBuffer(wb: ExcelJS.Workbook): Promise<ArrayBuffer> {
  return (await wb.xlsx.writeBuffer()) as ArrayBuffer;
}
