<script lang="ts">
  import { flip } from "svelte/animate";
  import {
    dndzone,
    TRIGGERS,
    SHADOW_ITEM_MARKER_PROPERTY_NAME,
    SHADOW_PLACEHOLDER_ITEM_ID,
    type DndEvent,
  } from "svelte-dnd-action";
  import { formatSheetTime } from "../dates";
  import type { Configuration, League } from "../model";
  import {
    boardColumns,
    fieldChoices,
    hintFromElement,
    isAwayCampus,
    kickoffChoices,
    resolveDrop,
    rowMatchesQuery,
    type BoardColumn,
    type SheetAction,
    type SheetRow,
  } from "../schedule-sheet";

  let {
    league,
    cfg,
    bracket,
    weekIso,
    highlightGame,
    highlightQuery,
    onAction,
  }: {
    league: League;
    cfg: Configuration;
    bracket: string;
    weekIso?: string;
    highlightGame?: string;
    highlightQuery?: string;
    onAction: (a: SheetAction) => void;
  } = $props();

  const flipDurationMs = 220;
  const GAME = "game";

  type DndRow = SheetRow & { isDndShadowItem?: boolean };

  let host: HTMLDivElement | undefined = $state();
  let dragging = $state(false);
  let draggedId = $state<string | null>(null);
  let dropKind = $state("");
  let hoverId = $state<string | null>(null);
  let lastX = 0;
  let lastY = 0;
  let columns = $state.raw<BoardColumn[]>([]);
  let timePads = $state.raw<Record<string, DndRow[]>>({});
  let fieldPads = $state.raw<Record<string, DndRow[]>>({});

  const times = $derived(kickoffChoices(league, cfg.games, bracket));
  const fields = $derived(fieldChoices(league, cfg.games, bracket));
  const ready = $derived(columns.some((c) => c.items.some((r) => !isShadow(r))));

  function isShadow(row: SheetRow): boolean {
    const r = row as DndRow;
    return !!r[SHADOW_ITEM_MARKER_PROPERTY_NAME] || row.id === SHADOW_PLACEHOLDER_ITEM_ID;
  }

  function realItems(items: DndRow[]): SheetRow[] {
    return items.filter((i) => !isShadow(i));
  }

  function neighborAfterShadow(items: DndRow[], pulledId: string): string | undefined {
    const idx = items.findIndex((i) => isShadow(i));
    const from = idx >= 0 ? idx + 1 : 0;
    for (let i = from; i < items.length; i++) {
      if (!isShadow(items[i]) && items[i].id !== pulledId) return items[i].id;
    }
    return undefined;
  }

  function listOptions(items: SheetRow[]) {
    return {
      items,
      flipDurationMs,
      type: GAME,
      dropTargetStyle: {} as Record<string, string>,
      dropTargetClasses: ["sheet-drop-target"],
      useCursorForDetection: true,
      centreDraggedOnCursor: true,
    };
  }

  function padOptions(items: DndRow[]) {
    return {
      ...listOptions(items),
      dragDisabled: true,
      morphDisabled: true,
    };
  }

  function syncBoard() {
    columns = boardColumns(league, cfg.games, bracket, weekIso);
    timePads = Object.fromEntries(kickoffChoices(league, cfg.games, bracket).map((t) => [t, []]));
    fieldPads = Object.fromEntries(fieldChoices(league, cfg.games, bracket).map((f) => [f.name, []]));
  }

  $effect.pre(() => {
    void cfg.games;
    void bracket;
    void weekIso;
    if (dragging) return;
    syncBoard();
  });

  $effect(() => {
    if (!host) return;
    host.setAttribute("data-sheet-ready", ready ? "yes" : "no");
    host.setAttribute("data-sheet-bracket", bracket);
    host.setAttribute("data-sheet-week", weekIso || "all");
    const hit = host.querySelector<HTMLElement>("[data-hit='yes']");
    hit?.scrollIntoView({ block: "nearest", inline: "nearest", behavior: "smooth" });
  });

  function trackMove(e: MouseEvent) {
    lastX = e.clientX;
    lastY = e.clientY;
  }

  function considerColumn(dateIso: string, e: CustomEvent<DndEvent<DndRow>>) {
    dragging = true;
    draggedId = String(e.detail.info.id);
    dropKind = "swap";
    columns = columns.map((c) => (c.dateIso === dateIso ? { ...c, items: e.detail.items } : c));
    hoverId =
      cardUnderCursor(String(e.detail.info.id)) ||
      neighborAfterShadow(e.detail.items, String(e.detail.info.id)) ||
      hoverId;
  }

  function considerPad(kind: "time" | "field", key: string, e: CustomEvent<DndEvent<DndRow>>) {
    dragging = true;
    draggedId = String(e.detail.info.id);
    dropKind = kind;
    if (kind === "time") timePads = { ...timePads, [key]: e.detail.items };
    else fieldPads = { ...fieldPads, [key]: e.detail.items };
  }

  function finishDrag() {
    dragging = false;
    draggedId = null;
    hoverId = null;
    dropKind = "";
  }

  function commit(id: string, dest: { type: "swap"; targetId: string } | { type: "time"; kickoff: string; dateIso?: string } | { type: "field"; field: string }) {
    const pulled = cfg.games.find((g) => g.id === id);
    finishDrag();
    if (!pulled) {
      syncBoard();
      return;
    }
    if (dest.type === "swap") {
      const target = cfg.games.find((g) => g.id === dest.targetId);
      if (target) onAction({ type: "swap", pulled, target });
      else syncBoard();
      return;
    }
    if (dest.type === "time") {
      if (pulled.kickoff === dest.kickoff && (!dest.dateIso || dest.dateIso === pulled.dateIso)) {
        syncBoard();
        return;
      }
      onAction({ type: "time", game: pulled, kickoff: dest.kickoff, dateIso: dest.dateIso });
      return;
    }
    if (pulled.field === dest.field) {
      syncBoard();
      return;
    }
    onAction({ type: "field", game: pulled, field: dest.field });
  }

  function cardUnderCursor(pulledId: string): string | undefined {
    const stack = document.elementsFromPoint(lastX, lastY);
    for (const el of stack) {
      if ((el as HTMLElement).id === "dnd-action-dragged-el") continue;
      const row = (el as HTMLElement).closest?.("[data-sheet-row][data-game]") as HTMLElement | null;
      const id = row?.getAttribute("data-game");
      if (id && id !== pulledId) return id;
    }
    return undefined;
  }

  function dropOutside(id: string) {
    const hit = resolveDrop(id, hintFromElement(document.elementFromPoint(lastX, lastY)));
    if (hit?.kind === "time" && hit.kickoff) {
      commit(id, { type: "time", kickoff: hit.kickoff, dateIso: hit.dateIso });
      return;
    }
    if (hit?.kind === "field" && hit.field) {
      commit(id, { type: "field", field: hit.field });
      return;
    }
    if (hit?.kind === "swap" && hit.targetId) {
      commit(id, { type: "swap", targetId: hit.targetId });
      return;
    }
    finishDrag();
    syncBoard();
  }

  function finalizeColumn(dateIso: string, e: CustomEvent<DndEvent<DndRow>>) {
    const trigger = e.detail.info.trigger;
    const id = String(e.detail.info.id);
    columns = columns.map((c) => (c.dateIso === dateIso ? { ...c, items: realItems(e.detail.items) } : c));
    if (trigger === TRIGGERS.DROPPED_INTO_ZONE) {
      const targetId = (hoverId && hoverId !== id ? hoverId : undefined) || cardUnderCursor(id);
      if (targetId) {
        commit(id, { type: "swap", targetId });
        return;
      }
      const pulled = cfg.games.find((g) => g.id === id);
      if (pulled && pulled.dateIso !== dateIso) {
        commit(id, { type: "time", kickoff: pulled.kickoff, dateIso });
        return;
      }
      finishDrag();
      syncBoard();
      return;
    }
    if (trigger === TRIGGERS.DROPPED_OUTSIDE_OF_ANY) dropOutside(id);
  }

  function finalizePad(kind: "time" | "field", key: string, e: CustomEvent<DndEvent<DndRow>>) {
    const trigger = e.detail.info.trigger;
    const id = String(e.detail.info.id);
    if (kind === "time") timePads = { ...timePads, [key]: [] };
    else fieldPads = { ...fieldPads, [key]: [] };
    if (trigger !== TRIGGERS.DROPPED_INTO_ZONE) return;
    if (kind === "time") commit(id, { type: "time", kickoff: key });
    else commit(id, { type: "field", field: key });
  }
</script>

<svelte:window onmousemove={trackMove} />

<div
  class="sheet-stage"
  class:sheet-dragging={dragging}
  role="application"
  data-sheet-host
  data-dnd-lib="svelte-dnd-action"
  data-board="trello"
  data-sheet-bracket={bracket}
  data-sheet-week={weekIso || "all"}
  data-drop-kind={dropKind}
  data-sheet-dragging={dragging ? "yes" : "no"}
  data-sheet-ready={ready ? "yes" : "no"}
  bind:this={host}
>
  <div class="sheet-rails" data-sheet-rails>
    <div class="sheet-rail" data-time-rail>
      <span class="rail-label">Time</span>
      {#each times as t (t)}
        <div class="chip chip-slot" data-time-slot={t}>
          <span class="chip-face">{formatSheetTime(t)}</span>
          <div
            class="chip-drop"
            use:dndzone={padOptions(timePads[t] || [])}
            onconsider={(e) => considerPad("time", t, e)}
            onfinalize={(e) => finalizePad("time", t, e)}
          >
            {#each timePads[t] || [] as item (item.id)}
              <div class="chip-shadow" animate:flip={{ duration: flipDurationMs }}></div>
            {/each}
          </div>
        </div>
      {/each}
    </div>
    <div class="sheet-rail" data-field-rail>
      <span class="rail-label">Field</span>
      {#each fields as f (f.name + f.campus)}
        <div class="chip chip-slot" data-field-slot={f.name} data-campus={f.campus}>
          <span class="chip-face">{f.label}</span>
          <div
            class="chip-drop"
            use:dndzone={padOptions(fieldPads[f.name] || [])}
            onconsider={(e) => considerPad("field", f.name, e)}
            onfinalize={(e) => finalizePad("field", f.name, e)}
          >
            {#each fieldPads[f.name] || [] as item (item.id)}
              <div class="chip-shadow" animate:flip={{ duration: flipDurationMs }}></div>
            {/each}
          </div>
        </div>
      {/each}
    </div>
  </div>

  <div class="sheet-scroll">
    <div class="sheet-board" data-season-grid>
      {#each columns as col, i (col.dateIso)}
        <section
          class="sheet-list"
          data-board-col={col.dateIso}
          data-week={col.dateIso}
          data-date-break={i > 0 ? col.dateIso : undefined}
        >
          <header class="sheet-list-head" data-col="date">
            <span class="list-date">{col.label}</span>
            <span class="list-long">{col.longLabel}</span>
            <span class="list-n">{col.items.filter((r) => !isShadow(r)).length}</span>
          </header>
          <div
            class="sheet-list-body"
            data-board-list={col.dateIso}
            use:dndzone={listOptions(col.items)}
            onconsider={(e) => considerColumn(col.dateIso, e)}
            onfinalize={(e) => finalizeColumn(col.dateIso, e)}
            aria-label={col.longLabel}
          >
            {#each col.items as row (row.id)}
              {@const hit = !isShadow(row) && rowMatchesQuery(row, highlightQuery, highlightGame)}
              <article
                class="sheet-card-game"
                class:sheet-row-lifted={draggedId === row.id}
                class:sheet-shadow={isShadow(row)}
                animate:flip={{ duration: flipDurationMs }}
                data-sheet-row={!isShadow(row) ? true : undefined}
                data-game={row.id}
                data-week={row.dateIso}
                data-bracket={row.bracket}
                data-home={row.homeLabel}
                data-away={row.awayLabel}
                data-location={row.location}
                data-away-campus={isAwayCampus(row.location) ? "yes" : "no"}
                data-time={row.time}
                data-kickoff={row.kickoff}
                data-field={row.field}
                data-street={row.street || undefined}
                data-hit={hit ? "yes" : "no"}
                aria-label={`${row.home} versus ${row.away}, ${row.time}, ${row.location}`}
              >
                {#if !isShadow(row)}
                  <div class="card-top">
                    <span data-grip aria-hidden="true">⠿</span>
                    <span
                      data-col="time"
                      data-drop="time"
                      data-game={row.id}
                      data-kickoff={row.kickoff}
                      data-week={row.dateIso}>{row.time}</span
                    >
                    <span class="card-date" data-col="date">{row.date}</span>
                  </div>
                  <p class="card-home" data-col="home">{row.home}</p>
                  <p class="card-away" data-col="away"><span class="vs">vs</span> {row.away}</p>
                  <p
                    class="card-loc"
                    data-col="location"
                    data-drop="field"
                    data-game={row.id}
                    data-field={row.field}
                    data-away-campus={isAwayCampus(row.location) ? "yes" : "no"}
                    title={row.street || undefined}
                    data-street={row.street || undefined}
                  >
                    {row.location}
                  </p>
                {/if}
              </article>
            {/each}
          </div>
        </section>
      {/each}
      {#if !columns.length}
        <p class="sheet-empty">No games in this bracket.</p>
      {/if}
    </div>
  </div>
</div>
