function paintRail(step: WizardStep, hasRoster: boolean) {
  const rail = document.querySelector("[data-wizard-rail]");
  if (!rail) return;
  const order = WIZARD_STEPS.map((s) => s.id);
  const cur = order.indexOf(step);
  for (const btn of rail.querySelectorAll<HTMLElement>("[data-wiz-step]")) {
    const id = btn.getAttribute("data-wiz-step") as WizardStep | null;
    const i = id ? order.indexOf(id) : -1;
    btn.setAttribute("aria-current", id === step ? "step" : "false");
    const canOpen = i === 0 || (hasRoster && i <= cur);
    btn.toggleAttribute("data-done", i >= 0 && i < cur && (id !== "drop" || hasRoster));
    btn.toggleAttribute("data-reachable", canOpen);
    btn.tabIndex = canOpen ? 0 : -1;
  }
}

function fieldClassOptions(selected: string): string {
  return NTSSA_FIELD_TYPES.map((t) => {
    const sel = t.name === selected ? " selected" : "";
    return `<option value="${esc(t.name)}"${sel}>${esc(t.name)} ${t.width}×${t.length} yd</option>`;
  }).join("");
}

function slotTicks(n: number): string {
  const count = Math.min(18, Math.max(0, n));
  return Array.from({ length: count }, () => "<i></i>").join("");
}

function rowClock(row: ClockRow): GameClock {
  return {
    warmupMinutes: row.warmupMinutes,
    firstHalfMinutes: row.firstHalfMinutes,
    secondHalfMinutes: row.secondHalfMinutes,
    waterBreakMinutes: row.waterBreakMinutes,
    halfTimeMinutes: row.halfTimeMinutes,
    vacateMinutes: row.vacateMinutes,
  };
}

function clockBarHtml(row: ClockRow): string {
  const c = rowClock(row);
  const occupy = occupyMinutes(c);
  const b = esc(row.bracket);
  const segs = clockSegments(c)
    .map((s) => {
      const flex = s.minutes > 0 ? s.minutes : 0.6;
      return `<div class="clock-seg" data-clock-seg="${s.id}" data-kind="${s.kind}" data-minutes="${s.minutes}" style="flex:${flex} 1 0">
        <span>${esc(s.label)}</span>
        <em>${s.minutes}</em>
        <i class="clock-handle" data-clock-handle="${s.part}" data-clock-bracket="${b}"></i>
      </div>`;
    })
    .join("");
  return `<div class="clock-bar" data-clock-bar data-on-clock="${row.onClockMinutes}" data-occupy="${occupy}" data-clock-bracket="${b}">${segs}</div>
    <div class="clock-parts">
      <label>Lead
        <input type="number" min="0" max="60" step="1" data-clock-field="warmupMinutes" data-clock-bracket="${b}" value="${row.warmupMinutes}" />
      </label>
      <label>1st half
        <input type="number" min="1" max="60" step="1" data-clock-field="firstHalfMinutes" data-clock-bracket="${b}" value="${row.firstHalfMinutes}" />
      </label>
      <label>Water
        <input type="number" min="0" max="20" step="1" data-clock-field="waterBreakMinutes" data-clock-bracket="${b}" value="${row.waterBreakMinutes}" />
      </label>
      <label>Half-time
        <input type="number" min="0" max="30" step="1" data-clock-field="halfTimeMinutes" data-clock-bracket="${b}" value="${row.halfTimeMinutes}" />
      </label>
      <label>2nd half
        <input type="number" min="1" max="60" step="1" data-clock-field="secondHalfMinutes" data-clock-bracket="${b}" value="${row.secondHalfMinutes}" />
      </label>
      <label>After
        <input type="number" min="0" max="40" step="1" data-clock-field="vacateMinutes" data-clock-bracket="${b}" value="${row.vacateMinutes}" />
      </label>
    </div>
    <p class="clock-sum" data-clock-sum>${row.playMinutes} min play · <strong>${row.onClockMinutes} min on the clock</strong> · ${row.warmupMinutes} lead · ${row.vacateMinutes} after</p>`;
}

function clockCardHtml(row: ClockRow): string {
  const badge = row.matchesNtssa
    ? `<span class="wiz-badge" data-clock-badge>NTSSA default</span>`
    : `<span class="wiz-badge" data-clock-badge data-custom="yes">custom clock</span>`;
  const b = esc(row.bracket);
  return `<section class="wiz-clock" data-wizard-clock="${b}" data-assumed="${row.assumed ? "yes" : "no"}" data-ntssa-match="${row.matchesNtssa ? "yes" : "no"}" data-format="${esc(row.format)}" data-on-clock="${row.onClockMinutes}">
    <header>
      <h3>${b}</h3>
      <em data-clock-teams>${row.teamCount} team${row.teamCount === 1 ? "" : "s"}</em>
      <span class="wiz-format" data-clock-format>${esc(row.format)}</span>
      ${badge}
    </header>
    ${clockBarHtml(row)}
    <div class="wiz-clock-grid">
      <label>Play (both halves)
        <input type="number" min="15" max="120" step="1" data-clock-field="gameLengthMinutes" data-clock-bracket="${b}" value="${row.gameLengthMinutes}" />
      </label>
      <label>Min on field
        <input type="number" min="1" max="11" step="1" data-clock-field="minOnField" data-clock-bracket="${b}" value="${row.minOnField}" />
      </label>
      <label>Max on field
        <input type="number" min="1" max="11" step="1" data-clock-field="maxOnField" data-clock-bracket="${b}" value="${row.maxOnField}" />
      </label>
      <label>Pitch class
        <select data-clock-field="fieldClasses" data-clock-bracket="${b}">${fieldClassOptions(row.fieldClass)}</select>
      </label>
      <label>Assistant refs min
        <input type="number" min="0" max="4" step="1" data-clock-field="assistantMin" data-clock-bracket="${b}" value="${row.assistantMin}" />
      </label>
      <label>Assistant refs preferred
        <input type="number" min="0" max="4" step="1" data-clock-field="assistantPreferred" data-clock-bracket="${b}" value="${row.assistantPreferred}" />
      </label>
    </div>
    <div class="wiz-slot-bar" data-clock-slots="${row.saturdaySlots}" style="--slots:${row.saturdaySlots}">
      <span class="wiz-ticks" data-clock-ticks>${slotTicks(row.saturdaySlots)}</span>
      <em data-clock-slot-line>${row.saturdaySlots} Saturday slots on one ${esc(row.fieldClass)} pitch · ${row.onClockMinutes} min on the clock + ${row.vacateMinutes} vacate</em>
    </div>
  </section>`;
}

export function patchClockCard(league: League, bracket: string) {
  const row = clockRows(league).find((r) => r.bracket === bracket);
  const card = document.querySelector<HTMLElement>(`[data-wizard-clock="${CSS.escape(bracket)}"]`);
  if (!row || !card) return;
  card.setAttribute("data-assumed", row.assumed ? "yes" : "no");
  card.setAttribute("data-ntssa-match", row.matchesNtssa ? "yes" : "no");
  card.setAttribute("data-format", row.format);
  const badge = card.querySelector("[data-clock-badge]");
  if (badge) {
    badge.textContent = row.matchesNtssa ? "NTSSA default" : "custom clock";
    badge.toggleAttribute("data-custom", !row.matchesNtssa);
  }
  const fmt = card.querySelector("[data-clock-format]");
  if (fmt) fmt.textContent = row.format;
  const bar = card.querySelector<HTMLElement>("[data-clock-slots]");
  if (bar) {
    bar.setAttribute("data-clock-slots", String(row.saturdaySlots));
    bar.style.setProperty("--slots", String(row.saturdaySlots));
  }
  const ticks = card.querySelector("[data-clock-ticks]");
  if (ticks) ticks.innerHTML = slotTicks(row.saturdaySlots);
  const line = card.querySelector("[data-clock-slot-line]");
  if (line) {
    line.textContent = `${row.saturdaySlots} Saturday slots on one ${row.fieldClass} pitch · ${row.onClockMinutes} min on the clock + ${row.vacateMinutes} vacate`;
  }
  card.setAttribute("data-on-clock", String(row.onClockMinutes));
  const barHost = card.querySelector("[data-clock-bar]");
  const parts = card.querySelector(".clock-parts");
  if (barHost && parts && !card.contains(document.activeElement)) {
    const wrap = document.createElement("div");
    wrap.innerHTML = clockBarHtml(row);
    barHost.replaceWith(wrap.querySelector("[data-clock-bar]")!);
    parts.replaceWith(wrap.querySelector(".clock-parts")!);
    const sum = card.querySelector("[data-clock-sum]");
    const nextSum = wrap.querySelector("[data-clock-sum]");
    if (sum && nextSum) sum.replaceWith(nextSum);
  } else {
    for (const input of card.querySelectorAll<HTMLInputElement>("[data-clock-field]")) {
      const f = input.getAttribute("data-clock-field") as keyof ClockRow | null;
      if (!f || input === document.activeElement) continue;
      const v = row[f];
      if (typeof v === "number") input.value = String(v);
    }
    const sum = card.querySelector("[data-clock-sum]");
    if (sum) {
      sum.innerHTML = `${row.playMinutes} min play · <strong>${row.onClockMinutes} min on the clock</strong> · ${row.warmupMinutes} lead · ${row.vacateMinutes} after`;
    }
  }
  const live = document.querySelector("[data-wizard-clocks-live]");
  if (live) live.textContent = clocksLiveLine(league);
}

function paintClocks(league: League) {
  const host = document.querySelector("[data-wizard-clocks]");
  if (!host) return;
  const editing = host.contains(document.activeElement);
  if (!editing) host.innerHTML = clockRows(league).map(clockCardHtml).join("");
  else for (const row of clockRows(league)) patchClockCard(league, row.bracket);
  const live = document.querySelector("[data-wizard-clocks-live]");
  if (live) live.textContent = clocksLiveLine(league);
  const season = document.querySelector("[data-wizard-season]");
  if (season && !season.contains(document.activeElement)) {
    const first = season.querySelector<HTMLInputElement>('[data-season-field="firstIso"]');
    const last = season.querySelector<HTMLInputElement>('[data-season-field="lastIso"]');
    const rematch = season.querySelector<HTMLInputElement>('[data-season-field="rematchCap"]');
    if (first) first.value = league.season.firstIso || "";
    if (last) last.value = league.season.lastIso || "";
    if (rematch) rematch.value = String(league.season.rematchCap || 2);
    season.toggleAttribute("data-assumed-window", !!league.season.assumedWindow);
  }
}

function paintFields(league: League, issues: ImportIssue[]) {
  ensureWizardFields(league);
  const hole = document.querySelector<HTMLElement>("[data-wizard-fields-hole]");
  const need = document.querySelector("[data-wizard-fields-need]");
  const cover = fieldsCoverBrackets(league);
  const missing = issues.find((i) => i.code === "missing-fields");
  if (need) need.textContent = fieldNeedLine(league);
  if (hole) {
    hole.hidden = cover.ok;
    hole.textContent = cover.missing.join(" ") || missing?.message || "";
  }
  const go = document.querySelector<HTMLButtonElement>("[data-wizard-continue-fields]");
  if (go) {
    go.disabled = !cover.ok;
    go.textContent = cover.ok
      ? "These fields look right — next: kids on each team"
      : cover.missing[0] || "Need a suitable pitch for each league";
  }
  const adopt = document.querySelector<HTMLButtonElement>("[data-wizard-adopt-van]");
  if (adopt) {
    const done = vanComplexAdopted(league);
    adopt.toggleAttribute("data-adopted", done);
    adopt.disabled = done;
    const label = adopt.querySelector("strong");
    if (label) label.textContent = done ? "Van Complex is named" : "We play at Van Complex";
  }
  const counts = document.querySelector("[data-wizard-field-counts]");
  if (counts) {
    const needSet = new Set(neededClasses(league));
    counts.innerHTML = FIELD_CLASSES.map((cls) => {
      const n = countOfClass(league, cls);
      const d = NTSSA_DRAW[cls];
      const min = needSet.has(cls) ? 1 : 0;
      const dec = n <= min ? " disabled" : "";
      return `<div class="wiz-count" data-field-count="${cls}">
        <strong>${cls}</strong>
        <span>${d.widthYd}×${d.lengthYd} yd · ${d.ages}</span>
        <button type="button" data-field-count-dec="${cls}"${dec}>−</button>
        <em data-field-count-n="${cls}">${n}</em>
        <button type="button" data-field-count-inc="${cls}">+</button>
      </div>`;
    }).join("");
  }
  const list = document.querySelector("[data-wizard-fields-list]");
  if (list) {
    const homePitches = league.fields.filter((f) => isHomeWizardPitch(league, f));
    list.innerHTML = homePitches
      .map(
        (f) =>
          `<li data-wizard-field="${esc(f.name)}"><span><strong>${esc(f.name)}</strong> · ${esc(f.type)} · ${esc(f.campus)}</span><button type="button" class="wiz-remove" data-wizard-remove-field="${esc(f.name)}">Remove</button></li>`,
      )
      .join("");
    (list as HTMLElement).hidden = !homePitches.length;
  }
  const form = document.querySelector("[data-wizard-pitch-form]");
  if (form && !form.contains(document.activeElement)) {
    const campus = form.querySelector<HTMLInputElement>("[data-pitch-campus]");
    const cls = form.querySelector<HTMLSelectElement>("[data-pitch-class]");
    const hours = form.querySelector<HTMLInputElement>("[data-pitch-hours]");
    if (campus && !campus.value) campus.value = league.fields[0]?.campus || "Van Complex";
    if (cls && !cls.value) {
      const needClass = clockRows(league).find((r) => r.teamCount)?.fieldClass || "small";
      cls.value = needClass;
    }
    if (hours && !hours.value) hours.value = DEFAULT_SATURDAY;
  }
}

function paintRefs(league: League) {
  const host = document.querySelector<HTMLElement>("[data-wizard-refs]");
  if (!host) return;
  const named = namedRefereeCount(league);
  const saved = !!league.season.proceedWithoutStaff;
  host.setAttribute("data-wizard-refs-saved", saved ? "yes" : "no");
  host.setAttribute("data-wizard-refs-warned", "yes");
  host.setAttribute("data-wizard-refs-named", named ? "yes" : "no");
  const need = host.querySelector("[data-wizard-refs-need]");
  if (need) need.textContent = refsNeedLine(league);
  const warn = host.querySelector<HTMLElement>("[data-wizard-refs-warn-line]");
  if (warn) {
    warn.hidden = !!named;
    warn.textContent = named ? "" : refsWarnLine(league);
  }
  const savedEl = host.querySelector<HTMLElement>("[data-wizard-refs-saved-line]");
  if (savedEl) {
    savedEl.hidden = !saved || !!named;
    savedEl.textContent = saved && !named ? "Recorded: schedule this season without named referee staff." : "";
  }
  const list = host.querySelector("[data-wizard-refs-list]");
  if (list) {
    list.innerHTML = league.staff
      .map(
        (s) =>
          `<li data-wizard-refs-person="${esc(printName(s))}"><span>${esc(staffLine(s))}</span><button type="button" class="wiz-remove" data-wizard-remove-ref="${esc(printName(s))}">Remove</button></li>`,
      )
      .join("");
    (list as HTMLElement).hidden = !named;
  }
  const form = host.querySelector("[data-wizard-ref-form]");
  if (form && !form.contains(document.activeElement)) {
    const centers = form.querySelector("[data-ref-centers]");
    if (centers) {
      const brackets = league.ageGroups.map((a) => a.name).filter(Boolean);
      centers.innerHTML = brackets
        .map(
          (b) =>
            `<label class="wiz-check"><input type="checkbox" data-ref-center value="${esc(b)}" checked /> ${esc(b)}</label>`,
        )
        .join("");
    }
  }
  const ack = host.querySelector<HTMLButtonElement>("[data-wizard-refs-warn]");
  if (ack) {
    ack.hidden = true;
    ack.disabled = true;
  }
  const without = host.querySelector<HTMLButtonElement>("[data-wizard-refs-without]");
  if (without) {
    without.hidden = !!named;
    without.disabled = !!named;
    without.textContent = saved
      ? "Continue without referee staff — next: away weeks"
      : "No referees — proceed without them";
  }
  const go = host.querySelector<HTMLButtonElement>("[data-wizard-refs-continue]");
  if (go) {
    go.hidden = !named;
    go.disabled = !named;
  }
}

function paintAway(league: League) {
  const host = document.querySelector<HTMLElement>("[data-wizard-away]");
  if (!host) return;
  const away = awayWeekends(league);
  const home = homeWeekends(league);
  host.setAttribute("data-wizard-away-n", String(away.length));
  host.setAttribute("data-wizard-home-n", String(home.length));
  const sats = playingSaturdays(league);
  const brackets = rosterGroups(league).map((g) => g.bracket);
  const orgs = [
    ...new Set([
      ...league.associations.filter((a) => !a.controlled).map((a) => a.name),
      ...away.map((w) => w.association),
      ...home.map((w) => w.association),
    ]),
  ];
  const form = host.querySelector("[data-wizard-away-form]");
  if (form && !form.contains(document.activeElement)) {
    const week = form.querySelector<HTMLSelectElement>("[data-away-week]");
    const leagueSel = form.querySelector<HTMLSelectElement>("[data-away-bracket]");
    const org = form.querySelector<HTMLInputElement>("[data-away-org]");
    const campus = form.querySelector<HTMLInputElement>("[data-away-campus]");
    const minutes = form.querySelector<HTMLInputElement>("[data-away-minutes]");
    const list = form.querySelector("#away-orgs");
    const places = form.querySelector("#away-campuses");
    if (week) {
      week.innerHTML = sats
        .map((d) => `<option value="${esc(d)}">${esc(formatLong(d))}</option>`)
        .join("");
    }
    if (leagueSel) {
      leagueSel.innerHTML = brackets.map((b) => `<option value="${esc(b)}">${esc(b)}</option>`).join("");
    }
    if (list) {
      list.innerHTML = orgs.map((n) => `<option value="${esc(n)}"></option>`).join("");
    }
    if (places) {
      const names = [
        ...new Set([
          ...league.campuses.map((c) => c.name).filter(Boolean),
          ...league.associations.filter((a) => !a.controlled && a.homeCampus).map((a) => a.homeCampus as string),
        ]),
      ];
      places.innerHTML = names.map((n) => `<option value="${esc(n)}"></option>`).join("");
    }
    if (org && !org.value && orgs[0]) org.placeholder = orgs[0];
    if (campus && !campus.value) campus.placeholder = orgs[0] ? `${orgs[0]} Complex` : "e.g. Mineola Complex";
    if (minutes && !minutes.value) minutes.placeholder = "e.g. 35";
  }
  const ul = host.querySelector("[data-wizard-away-list]");
  if (ul) {
    const placeLine = (w: AwayWeekend) => {
      const bits = [w.campus, w.minutes != null ? `${w.minutes} min` : ""].filter(Boolean);
      return bits.length ? ` (${bits.join(", ")})` : "";
    };
    const awayItems = away.map(
      (w) =>
        `<li data-wizard-away-row="${esc(w.dateIso)}|${esc(w.bracket)}|${esc(w.association)}" data-kind="away" data-campus="${esc(w.campus || "")}" data-minutes="${w.minutes ?? ""}"><span><strong>${esc(formatLong(w.dateIso))}</strong> · ${esc(w.bracket)} — we travel to ${esc(w.association)}${esc(placeLine(w))}</span><button type="button" class="wiz-remove" data-wizard-remove-away="${esc(w.dateIso)}|${esc(w.bracket)}|${esc(w.association)}">Remove</button></li>`,
    );
    const homeItems = home.map(
      (w) =>
        `<li data-wizard-home-row="${esc(w.dateIso)}|${esc(w.bracket)}|${esc(w.association)}" data-kind="here" data-campus="${esc(w.campus || "")}" data-minutes="${w.minutes ?? ""}"><span><strong>${esc(formatLong(w.dateIso))}</strong> · ${esc(w.bracket)} — ${esc(w.association)} comes HERE${esc(placeLine(w))}</span><button type="button" class="wiz-remove" data-wizard-remove-home="${esc(w.dateIso)}|${esc(w.bracket)}|${esc(w.association)}">Remove</button></li>`,
    );
    ul.innerHTML = [...awayItems, ...homeItems].join("");
    (ul as HTMLElement).hidden = !away.length && !home.length;
  }
  const need = host.querySelector("[data-wizard-away-need]");
  if (need) {
    const n = away.length + home.length;
    need.textContent = n
      ? `${away.length} we travel · ${home.length} they come here.`
      : "No interleague weekends yet. Add a travel Saturday or a HERE Saturday, or skip if every week is ours.";
  }
}

function paintDone(
  league: League,
  games: PlacedGame[],
  requested?: string,
  extra?: { editing?: boolean; scoreLine?: string; conflicts?: LiveConflict[]; canUndo?: boolean; person?: string },
) {
  const host = document.querySelector<HTMLElement>("[data-wizard-done]");
  if (!host) return;
  const tabs = sheetBrackets(games);
  const active = defaultLeagueSheet(games, requested);
  const editing = !!extra?.editing;
  const conflicts = extra?.conflicts || [];
  const conflictIds = new Set(conflicts.flatMap((c) => c.gameIds));
  const person = extra?.person || "";
  const people = schedulePeople(league, games);
  host.setAttribute("data-wizard-sheet-bracket", active);
  host.setAttribute("data-wizard-editing", editing ? "yes" : "no");
  host.setAttribute("data-wizard-conflict-n", String(conflicts.length));
  host.setAttribute("data-wizard-preview", person);
  const nav = host.querySelector<HTMLElement>("[data-wizard-sheet-tabs]");
  if (nav) {
    nav.innerHTML = tabs
      .map(
        (b) =>
          `<button type="button" class="wiz-sheet-tab" data-wizard-sheet-tab="${esc(b)}" aria-current="${b === active ? "true" : "false"}">${esc(b)}</button>`,
      )
      .join("");
    nav.hidden = !tabs.length;
  }
  const score = host.querySelector<HTMLElement>("[data-wizard-edit-score]");
  if (score) {
    score.hidden = !games.length;
    score.textContent = extra?.scoreLine || "";
  }
  const clash = host.querySelector<HTMLElement>("[data-wizard-edit-conflicts]");
  if (clash) {
    clash.hidden = !games.length;
    clash.setAttribute("data-n", String(conflicts.length));
    clash.innerHTML = conflicts.length
      ? conflicts.map((c) => `<li data-conflict-kind="${esc(c.kind)}">${esc(c.text)}</li>`).join("")
      : `<li data-conflict-kind="none">No conflicts.</li>`;
  }
  const editBtn = host.querySelector<HTMLButtonElement>("[data-wizard-edit-schedule]");
  if (editBtn) {
    editBtn.hidden = !games.length;
    editBtn.textContent = editing ? "Done editing" : "Edit this schedule";
    editBtn.setAttribute("aria-pressed", editing ? "true" : "false");
  }
  const undo = host.querySelector<HTMLButtonElement>("[data-wizard-undo-edit]");
  if (undo) undo.hidden = !editing || !extra?.canUndo;
  const hint = host.querySelector<HTMLElement>("[data-wizard-edit-hint]");
  if (hint) {
    hint.hidden = !editing;
    hint.textContent = editing
      ? "Drag a TIME onto another TIME to swap kickoffs. Drag HOME or AWAY onto another club to swap who plays whom. Score and conflicts update immediately."
      : "";
  }
  const pick = host.querySelector<HTMLSelectElement>("[data-wizard-person]");
  if (pick && !pick.matches(":focus")) {
    const groups = [
      { kind: "coach" as const, label: "Coaches" },
      { kind: "referee" as const, label: "Referees" },
    ];
    pick.innerHTML =
      `<option value="">Whole league</option>` +
      groups
        .map((g) => {
          const opts = people.filter((p) => p.kind === g.kind);
          if (!opts.length) return "";
          return `<optgroup label="${esc(g.label)}">${opts
            .map((p) => `<option value="${esc(p.id)}"${p.id === person ? " selected" : ""}>${esc(p.name)}</option>`)
            .join("")}</optgroup>`;
        })
        .join("");
    pick.hidden = !people.length && !games.length;
    pick.disabled = editing;
  }
  const line = host.querySelector<HTMLElement>("[data-wizard-person-line]");
  if (line) {
    if (!person) {
      line.hidden = true;
      line.textContent = "";
    } else {
      const mine = gamesForPerson(league, games, person);
      const n = liveConflicts(league, games).filter((c) => c.gameIds.some((id) => mine.some((g) => g.id === id))).length;
      line.hidden = false;
      line.textContent = n
        ? `${person}: ${mine.length} game${mine.length === 1 ? "" : "s"} · ${n} conflict${n === 1 ? "" : "s"}`
        : `${person}: ${mine.length} game${mine.length === 1 ? "" : "s"} · no conflicts`;
      line.setAttribute("data-conflict", n ? "yes" : "no");
    }
  }
  if (nav) nav.hidden = !!person || !tabs.length;
  const sheet = host.querySelector("[data-wizard-sheet]");
  if (sheet) {
    if (!games.length) {
      sheet.innerHTML = `<p class="wiz-live" data-wizard-sheet-empty>No games placed yet. Go back to Build.</p>`;
    } else if (person) {
      sheet.innerHTML = personPreviewHtml(league, games, person);
    } else {
      sheet.innerHTML = leagueSheetHtml(league, games, active, { editing, conflictIds });
    }
  }
}

function paintKids(league: League) {
  const host = document.querySelector<HTMLElement>("[data-wizard-kids]");
  if (!host) return;
  const hollow = hollowTeams(league);
  const saved = !!league.season.proceedWithoutPlayers;
  const full = !hollow.length;
  host.setAttribute("data-wizard-kids-saved", saved ? "yes" : "no");
  const need = host.querySelector("[data-wizard-kids-need]");
  if (need) need.textContent = kidsNeedLine(league);
  const savedEl = host.querySelector<HTMLElement>("[data-wizard-kids-saved-line]");
  if (savedEl) {
    savedEl.hidden = !saved;
    savedEl.textContent = saved ? "Recorded: schedule this season without player names." : "";
  }
  const list = host.querySelector("[data-wizard-kids-hollow]");
  if (list) {
    list.innerHTML = hollow
      .map((t) => `<li data-wizard-kids-team="${esc(teamLabel(t))}">${esc(teamLabel(t))} — no players listed</li>`)
      .join("");
    (list as HTMLElement).hidden = !hollow.length;
  }
  const without = host.querySelector<HTMLButtonElement>("[data-wizard-kids-without]");
  if (without) {
    without.hidden = full && !saved;
    without.disabled = false;
    without.textContent = saved
      ? "Continue without player names — next: referees"
      : "We don’t need player names — proceed without that data";
  }
  const go = host.querySelector<HTMLButtonElement>("[data-wizard-kids-continue]");
  if (go) {
    go.hidden = !full;
    go.disabled = !full;
  }
}

export function paintWizard(opts: {
  league: League | null;
  issues: ImportIssue[];
  report: string[];
  step: WizardStep;
  dedupeLine?: string;
  games?: PlacedGame[];
  sheetBracket?: string;
  editing?: boolean;
  scoreLine?: string;
  conflicts?: LiveConflict[];
  canUndo?: boolean;
  person?: string;
}) {
  const { league, issues, report, step, dedupeLine, games, sheetBracket, editing, scoreLine, conflicts, canUndo, person } = opts;
  const hasRoster = !!league?.teams.length;
  paintRail(step, hasRoster);
  const lead = document.querySelector("[data-wizard-lead]");
  if (lead) {
    lead.textContent =
      step === "drop" && hasRoster
        ? "These are the teams we read. Duplicate rows and empty table padding were skipped."
        : LEADS[step];
  }
  const drop = document.querySelector<HTMLElement>("[data-wizard-drop]");
  const roster = document.querySelector<HTMLElement>("[data-wizard-roster]");
  const settings = document.querySelector<HTMLElement>("[data-wizard-settings]");
  const fields = document.querySelector<HTMLElement>("[data-wizard-fields]");
  const kids = document.querySelector<HTMLElement>("[data-wizard-kids]");
  const refs = document.querySelector<HTMLElement>("[data-wizard-refs]");
  const away = document.querySelector<HTMLElement>("[data-wizard-away]");
  const plan = document.querySelector<HTMLElement>("[data-wizard-plan]");
  const done = document.querySelector<HTMLElement>("[data-wizard-done]");
  if (drop) drop.hidden = step !== "drop" || hasRoster;
  if (roster) roster.hidden = step !== "drop" || !hasRoster;
  if (settings) settings.hidden = step !== "settings";
  if (fields) fields.hidden = step !== "fields";
  if (kids) kids.hidden = step !== "kids";
  if (refs) refs.hidden = step !== "refs";
  if (away) away.hidden = step !== "away";
  if (plan) plan.hidden = step !== "plan";
  if (done) done.hidden = step !== "done";

  const go = document.querySelector<HTMLButtonElement>("[data-wizard-continue]");
  if (go) go.disabled = !hasRoster;

  if (!league) return;

  if (roster) {
    const groups = rosterGroups(league);
    const teamN = league.teams.length;
    const coachN = league.teams.filter((t) => t.coach || t.assistant).length;
    const summary = roster.querySelector("[data-wizard-summary]");
    if (summary) {
      const title = league.season.headerTitle || league.season.title || "this roster";
      summary.innerHTML = `<strong>${esc(title)}</strong> — ${teamN} team${teamN === 1 ? "" : "s"}, ${groups.length} bracket${groups.length === 1 ? "" : "s"}, ${coachN} with a coach listed.`;
    }
    const dedupe = roster.querySelector("[data-wizard-dedupe]");
    if (dedupe) {
      const line = dedupeLine || report.find((r) => /blank table|duplicate coach|merged /i.test(r));
      dedupe.textContent = line || "";
      (dedupe as HTMLElement).hidden = !line;
    }
    const host = roster.querySelector("[data-wizard-brackets]");
    if (host) {
      host.innerHTML = groups
        .map((g) => {
          const rows = g.teams
            .map((t) => {
              const asst = t.assistant ? `<span class="wiz-asst">${esc(t.assistant)}</span>` : `<span class="wiz-miss">no assistant listed</span>`;
              const coach = t.coach ? esc(t.coach) : `<span class="wiz-miss">no head coach listed</span>`;
              return `<li data-wizard-team="${esc(t.key)}"><strong>${esc(t.name)}</strong><span class="wiz-coach">${coach}</span>${asst}</li>`;
            })
            .join("");
          return `<section class="wiz-bracket" data-wizard-bracket="${esc(g.bracket)}"><h3>${esc(g.bracket)} <em>${g.teams.length}</em></h3><ul>${rows}</ul></section>`;
        })
        .join("");
    }
    const holes = roster.querySelector("[data-wizard-holes]");
    if (holes) {
      const lines = holeLines(issues, league);
      holes.innerHTML = lines.map((m) => `<li>${esc(m)}</li>`).join("");
      (holes as HTMLElement).hidden = !lines.length;
    }
  }

  if (step === "settings") paintClocks(league);
  if (step === "fields") paintFields(league, issues);
  if (step === "kids") paintKids(league);
  if (step === "refs") paintRefs(league);
  if (step === "away") paintAway(league);
  if (step === "done") paintDone(league, games || [], sheetBracket, { editing, scoreLine, conflicts, canUndo, person });
}
